const DATA_MODULES=['agenda','aprovacoes','arquivos','calendario','campanhas','configuracoes','conteudos','equipe','eventos','ideias','instagram','integracoes','lixeira','projetos','relatorios','solicitacoes','tarefas','templates','trafego'];
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const attr=v=>esc(v).replace(/`/g,'&#96;');
const num=v=>{if(typeof v==='number')return Number.isFinite(v)?v:0;let s=String(v??'').trim();if(!s)return 0;if(s.includes(',')&&s.includes('.'))s=s.replace(/\./g,'').replace(',','.');else if(s.includes(','))s=s.replace(',','.');const n=Number(s);return Number.isFinite(n)?n:0};
const money=v=>num(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const pct=v=>`${(num(v)||0).toLocaleString('pt-BR',{maximumFractionDigits:1})}%`;
const fmtDate=v=>{if(!v)return '—';const d=new Date(String(v).length===10?`${v}T12:00:00`:v);return isNaN(d)?String(v):new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'}).format(d)};
const fmtDateTime=v=>{if(!v)return '—';const d=new Date(v);return isNaN(d)?String(v):new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}).format(d)};
const today=()=>new Date().toISOString().slice(0,10);
const isoDate=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);
const debounce=(fn,ms=250)=>{let t;return(...a)=>{clearTimeout(t);t=setTimeout(()=>fn(...a),ms)}};

// v3.3.1 — perfis internos locais da equipe
const INTERNAL_USERS=[
 {code:'NAT-3301',name:'Natália Mello',role:'manager',label:'Gerente de Marketing'},
 {code:'ANT-3302',name:'Antônio Filho',role:'team',label:'Equipe de Marketing'},
 {code:'MON-3303',name:'Monique Vilante',role:'team',label:'Equipe de Marketing'},
 {code:'ALU-3304',name:'Aluizo Junior',role:'team',label:'Equipe de Marketing'},
 {code:'EDU-3305',name:'Maria Eduarda',role:'team',label:'Equipe de Marketing'}
];
const TEAM_ALLOWED=['minhaarea','agenda','calendario','tarefas','projetos','eventos','conteudos','ideias','campanhas','aprovacoes','instagram','trafego','templates','arquivos'];
let internalSession=null;
function loadInternalSession(){try{const x=JSON.parse(sessionStorage.getItem('evo.internal.session')||'null');if(x&&INTERNAL_USERS.some(u=>u.code===x.code&&u.name===x.name))return x}catch{}return null}
function canAccess(page){if(!internalSession)return false;return internalSession.role==='manager'||TEAM_ALLOWED.includes(page)}
function renderInternalLogin(){
 document.body.classList.add('internal-login-mode');
 document.getElementById('app').style.display='none';
 let box=document.getElementById('internalLogin');
 if(!box){box=document.createElement('div');box.id='internalLogin';document.body.appendChild(box)}
 box.innerHTML=`<div class="internal-login-wrap"><div class="internal-login-card"><div class="brandmark loginmark">E</div><small>COLÉGIO EVOLUÇÃO</small><h1>EVO MKT</h1><p>Acesso interno da equipe de Marketing</p><label>Código de acesso</label><input id="internalCode" autocomplete="off" placeholder="Ex.: ANT-3302"><div id="internalLoginError"></div><button class="btn" id="internalLoginBtn">Entrar</button><div class="internal-login-note">Cada integrante abre direto na própria Minha Área. A Gerente possui acesso administrativo completo.</div></div></div>`;
 const login=()=>{const code=document.getElementById('internalCode').value.trim().toUpperCase();const u=INTERNAL_USERS.find(x=>x.code===code);if(!u){document.getElementById('internalLoginError').innerHTML='<div class="login-error">Código inválido.</div>';return}internalSession={code:u.code,name:u.name,role:u.role,label:u.label};sessionStorage.setItem('evo.internal.session',JSON.stringify(internalSession));setPref('currentUser',u.name);box.remove();document.body.classList.remove('internal-login-mode');document.getElementById('app').style.display='flex';startApp()};
 document.getElementById('internalLoginBtn').onclick=login;document.getElementById('internalCode').onkeydown=e=>{if(e.key==='Enter')login()};setTimeout(()=>document.getElementById('internalCode')?.focus(),30)
}
function logoutInternal(){sessionStorage.removeItem('evo.internal.session');internalSession=null;location.href=location.pathname}
function renderInternalUser(){const el=document.getElementById('internalUser');if(!el||!internalSession)return;el.innerHTML=`<div class="internal-avatar">${esc(internalSession.name[0])}</div><div><b>${esc(internalSession.name)}</b><small>${esc(internalSession.label)}</small></div><button id="internalLogout" class="internal-logout" title="Sair">Sair</button>`;document.getElementById('internalLogout').onclick=logoutInternal}


