 $('#prevPage')&&($('#prevPage').onclick=()=>{state.pageNum--;renderModule()});$('#nextPage')&&($('#nextPage').onclick=()=>{state.pageNum++;renderModule()});$('#pageSize')&&($('#pageSize').onchange=e=>{state.pageSize=Number(e.target.value);setPref('pageSize',state.pageSize);state.pageNum=1;renderModule()});
