 const next=wf.idx+1;if(next>=wf.cfg.stages.length)return toast('Fluxo já concluído','ok');
 const st=wf.cfg.stages[next],isFinal=next===wf.cfg.stages.length-1,responsavel=st.responsavel||r.responsavel||'';const newList=(st.checklist||[]).map(text=>({text,done:false}));const events=collabEvents(r);events.push(workflowEvent(`Etapa ${wf.stage.name} concluída → ${st.name}`,{de:wf.stage.name,para:st.name,responsavel}));
