function collabEvents(r){try{const v=JSON.parse(r?.colaboracaoEquipe||'[]');return Array.isArray(v)?v:[]}catch{return []}}
function collabAuthor(){return internalSession?.name||pref('currentUser','Equipe')||'Equipe'}
function collabEvent(type,text,extra={}){return {type,autor:collabAuthor(),em:new Date().toISOString(),text:String(text||'').trim(),...extra}}
function collabIcon(t){return ({comentario:'💬',arquivo:'📎',ajuda:'🙋',bloqueio:'⛔',desbloqueio:'✅',dependencia:'🔗',etapa:'✓',fluxo:'⇢'})[t]||'•'}
function collabType(t){return ({comentario:'Comentário',arquivo:'Arquivo/referência',ajuda:'Pedido de ajuda',bloqueio:'Bloqueio',desbloqueio:'Desbloqueado',dependencia:'Dependência',etapa:'Etapa concluída',fluxo:'Fluxo automático'})[t]||'Atualização'}
function collabMentionHTML(text,names){let out=esc(text||'');const aliases=[];(names||[]).forEach(n=>{aliases.push(n);const first=String(n).trim().split(/\s+/)[0];if(first)aliases.push(first)});[...new Set(aliases)].sort((a,b)=>b.length-a.length).forEach(n=>{const safe=esc(n);const re=new RegExp('@'+safe.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi');out=out.replace(re,`<button class=\"timeline-mention\" data-name=\"${attr(n)}\">@${safe}</button>`)});return out}

