async function openCollaboration(module,id){const r=await collabRow(module,id);if(!r)return toast('Item não encontrado','warn');const data=await allData(['equipe','tarefas','agenda','projetos','conteudos','solicitacoes','eventos']);const names=personNames(data);document.body.insertAdjacentHTML('beforeend',collaborationHTML(module,r,names));const overlay=document.getElementById('collabOverlay');const txt=document.getElementById('collabText');document.getElementById('closeCollab').onclick=closeCollab;overlay.onclick=e=>{if(e.target===overlay)closeCollab()};document.querySelectorAll('.mention-chip').forEach(b=>b.onclick=()=>{txt.value+=(txt.value?' ':'')+'@'+b.dataset.name;txt.focus()});document.querySelectorAll('.timeline-mention').forEach(b=>b.onclick=()=>{const who=b.dataset.name;if(internalSession?.role==='manager'){setPref('currentUser',who);closeCollab();go('minhaarea')}else toast(`Menção a ${who}`)});async function saveEvent(event,patch={}){const fresh=await collabRow(module,id);const events=collabEvents(fresh);events.push(event);await patchWork(module,id,{...patch,colaboracaoEquipe:JSON.stringify(events)});toast('Colaboração registrada');closeCollab();invalidate(module);if(state.page==='minhaarea')renderMyArea();else if(state.module===module)loadModule(module,true)}document.getElementById('flowStart')&&(document.getElementById('flowStart').onclick=async()=>{await startWorkflow(module,id);closeCollab();openCollaboration(module,id)});document.getElementById('flowAdvance')&&(document.getElementById('flowAdvance').onclick=async()=>{await advanceWorkflow(module,id);closeCollab();openCollaboration(module,id)});document.getElementById('flowOpenManager')&&(document.getElementById('flowOpenManager').onclick=()=>{closeCollab();internalSession?.role==='manager'?go('fluxos'):toast('A configuração do fluxo é gerenciada pela Gerente')});document.querySelectorAll('.flow-check').forEach(c=>c.onchange=async()=>{await toggleWorkflowCheck(module,id,Number(c.dataset.index));closeCollab();openCollaboration(module,id)});document.getElementById('collabComment').onclick=async()=>{if(!txt.value.trim())return toast('Escreva um comentário','warn');await saveEvent(collabEvent('comentario',txt.value))};document.getElementById('collabFile').onclick=async()=>{const ref=prompt('Cole o caminho do arquivo na rede/local ou uma URL de referência:');if(!ref?.trim())return;await saveEvent(collabEvent('arquivo','Arquivo ou referência compartilhada',{ref:ref.trim()}),{anexosInternos:[r.anexosInternos,ref.trim()].filter(Boolean).join('\n')})};document.getElementById('collabHelp').onclick=async()=>{const why=prompt('Que ajuda você precisa?');if(!why?.trim())return;await saveEvent(collabEvent('ajuda',why),{pedidoAjuda:why.trim(),pedidoAjudaPor:collabAuthor(),pedidoAjudaEm:new Date().toISOString()})};document.getElementById('collabBlock').onclick=async()=>{if(r.bloqueadoPor){await saveEvent(collabEvent('desbloqueio','Bloqueio removido'),{bloqueadoPor:'',bloqueadoEm:''})}else{const why=prompt('O que está bloqueando este item?');if(!why?.trim())return;await saveEvent(collabEvent('bloqueio',why),{bloqueadoPor:why.trim(),bloqueadoEm:new Date().toISOString()})}};document.getElementById('collabDependency').onclick=async()=>{const dep=prompt('Informe o ID ou título do item do qual este trabalho depende:');if(!dep?.trim())return;await saveEvent(collabEvent('dependencia',dep),{dependenciaDe:dep.trim()})};document.getElementById('collabStage').onclick=async()=>{const stage=prompt('Qual etapa foi concluída?');if(!stage?.trim())return;await saveEvent(collabEvent('etapa',stage),{ultimaEtapaConcluida:stage.trim(),etapaConcluidaPor:collabAuthor(),etapaConcluidaEm:new Date().toISOString()})}}

