async function renderGovernance(){
 if(internalSession?.role!=='manager')return go('minhaarea');
 const data=await allData(['equipe','tarefas','projetos','conteudos','solicitacoes','eventos','campanhas','agenda']);
 const snap=operationalSnapshot(data),gp=governancePrefs(),items=snap.items,people=snap.people;
 const critical=items.filter(r=>r._risk>=70),high=items.filter(r=>r._risk>=50&&r._risk<70),preventive=items.filter(r=>r._risk>=gp.alertThreshold&&daysUntil(recordDate(r))>=0);
 const overdue=items.filter(r=>daysUntil(recordDate(r))<0),overloaded=people.filter(p=>p.load>=90),blocked=items.filter(r=>r.bloqueadoPor||r.dependenciaDe);
 const month=new Date().toISOString().slice(0,7);const all=Object.values(data).flatMap(x=>Array.isArray(x)?x:[]);const doneMonth=all.filter(r=>isClosedRecord(r)&&String(r.atualizadoEm||r.aprovadoSolicitanteEm||r.publicacaoEm||'').slice(0,7)===month).length;
 const goalPct=Math.min(100,Math.round(doneMonth/Math.max(1,gp.monthlyGoal)*100));const onTimeBase=Math.max(1,doneMonth+overdue.length),onTime=Math.max(0,Math.round(doneMonth/onTimeBase*100));
 $('#content').innerHTML=`<div class="dashboard-head"><div><small>GOVERNANÇA OPERACIONAL</small><h1>Risco, capacidade e metas</h1><p>Alertas preventivos calculados por regras locais e explicáveis.</p></div><div><button class="softbtn" id="govExport">Exportar riscos</button><button class="softbtn" id="govConfig">Configurar metas</button></div></div>
 <div class="kpis"><div class="kpi red"><small>Risco crítico</small><strong>${critical.length}</strong></div><div class="kpi orange"><small>Risco alto</small><strong>${high.length}</strong></div><div class="kpi"><small>Equipe sobrecarregada</small><strong>${overloaded.length}</strong></div><div class="kpi green"><small>Meta mensal</small><strong>${goalPct}%</strong></div></div>
 <div class="governance-grid"><section class="card span2"><div class="card-title"><div><small>PREVENÇÃO</small><h3>Itens com risco antes do prazo</h3></div><span class="alert-pill">${preventive.length} alerta(s)</span></div>${preventive.slice(0,12).map(r=>`<button class="risk-row" data-go="${r._module}"><span class="risk-score ${riskClass(r._risk)}">${r._risk}</span><div><b>${esc(r.titulo||r._label)}</b><small>${esc(r._label)} · ${esc(r.responsavel||'Sem responsável')} · ${riskLevel(r._risk)}<br>${esc(r._riskReason||'')}</small></div><time>${fmtDate(recordDate(r))}</time></button>`).join('')||'<div class="empty compact">Nenhum risco preventivo acima do limite configurado.</div>'}</section>
 <section class="card"><div class="card-title"><div><small>CAPACIDADE</small><h3>Carga por pessoa</h3></div></div>${people.sort((a,b)=>b.load-a.load).map(p=>`<div class="capacity-row"><div><b>${esc(p.name)}</b><small>${p.cap?p.cap+'h/sem':'capacidade padrão'} · ${p.st.open.length} item(ns)</small></div><div class="capacity-bar"><i style="width:${p.load}%"></i></div><strong class="${p.load>=90?'danger-text':''}">${p.load}%</strong></div>`).join('')||'<div class="empty compact">Sem integrantes suficientes para calcular carga.</div>'}</section>
 <section class="card"><div class="card-title"><div><small>METAS</small><h3>Saúde da operação</h3></div></div><div class="goal-ring"><strong>${goalPct}%</strong><span>${doneMonth}/${gp.monthlyGoal} entregas no mês</span></div><div class="goal-line"><span>Entregas no prazo</span><b>${onTime}%</b></div><div class="goal-line"><span>Meta de pontualidade</span><b>${gp.targetOnTime}%</b></div><div class="goal-line"><span>Máx. atrasados tolerados</span><b>${gp.maxOverdue}</b></div></section>
 <section class="card"><div class="card-title"><div><small>EQUILÍBRIO</small><h3>Sugestões de redistribuição</h3></div></div>${rebalanceSuggestions(people).map(x=>`<div class="rebalance-row"><div><b>${esc(x.from)}</b><small>${x.fromLoad}% de carga</small></div><span>→</span><div><b>${esc(x.to)}</b><small>${x.toLoad}% de carga</small></div><strong>até ${x.count} item(ns)</strong></div>`).join('')||'<div class="empty compact">Nenhuma redistribuição sugerida neste momento.</div>'}</section><section class="card span2"><div class="card-title"><div><small>GARGALOS</small><h3>Onde a operação está travando</h3></div></div><div class="bottleneck-grid"><div><b>${overdue.length}</b><span>Atrasados</span></div><div><b>${blocked.length}</b><span>Bloqueados/dependências</span></div><div><b>${overloaded.length}</b><span>Pessoas ≥90% carga</span></div><div><b>${items.filter(r=>r.fluxoEtapaPrazo&&daysUntil(r.fluxoEtapaPrazo)<0).length}</b><span>SLAs internos vencidos</span></div></div></section></div>`;
 bindGoButtons();
 $('#govExport').onclick=()=>exportCSV('GOVERNANCA_RISCOS',items.filter(r=>r._risk>=gp.alertThreshold).map(r=>({modulo:r._label,titulo:r.titulo,responsavel:r.responsavel,prazo:recordDate(r),prioridade:r.prioridade,score:r._risk,nivel:riskLevel(r._risk),motivo:r._riskReason})));
 $('#govConfig').onclick=()=>{const m=Number(prompt('Meta mensal de entregas:',gp.monthlyGoal));if(!m)return;const late=Number(prompt('Máximo de itens atrasados tolerados:',gp.maxOverdue));const target=Number(prompt('Meta de entregas no prazo (%):',gp.targetOnTime));const th=Number(prompt('Score mínimo para alerta preventivo (0-100):',gp.alertThreshold));saveGovernancePrefs({monthlyGoal:m,maxOverdue:Number.isFinite(late)?late:gp.maxOverdue,targetOnTime:Number.isFinite(target)?target:gp.targetOnTime,alertThreshold:Number.isFinite(th)?th:gp.alertThreshold});renderGovernance()}
}


// v3.5.0 — planejamento estratégico e qualidade operacional
const STRATEGIC_SEGMENTS=['Infantil','Anos Iniciais','Anos Finais','Ensino Médio'];
function strategyPrefs(){return pref('strategy',{period:'mensal',focus:'Equilibrar produção, qualidade e prazos do marketing.',goals:{contents:20,campaigns:2,projects:4,events:6,onTime:90,quality:90},weeklyReview:''})}
function saveStrategyPrefs(v){setPref('strategy',v)}
function strategyDate(r,m=''){return String(m==='conteudos'?(r.publicacaoEm||r.prazo||r.dataInicio||''):m==='campanhas'?(r.dataInicio||r.prazo||''):m==='eventos'?(r.dataInicio||r.prazo||''):m==='projetos'?(r.atualizadoEm||r.prazo||r.dataInicio||''):(r.atualizadoEm||r.prazo||r.dataInicio||'')).slice(0,10)}
function currentMonth(v){return String(v||'').slice(0,7)===new Date().toISOString().slice(0,7)}
function qualityAudit(data){const out=[];const defs=[['tarefas','Tarefa'],['conteudos','Conteúdo'],['campanhas','Campanha'],['projetos','Projeto'],['eventos','Evento'],['solicitacoes','Demanda']];defs.forEach(([m,label])=>(data[m]||[]).forEach(r=>{if(isClosedRecord(r)&&m!=='conteudos')return;const title=r.titulo||label;if(!r.responsavel&&m!=='campanhas')out.push({...r,_module:m,_quality:`${label} sem responsável`,_severity:'ALTA'});if(!recordDate(r)&&['tarefas','conteudos','projetos','eventos','solicitacoes'].includes(m))out.push({...r,_module:m,_quality:`${label} sem prazo/data`,_severity:'MÉDIA'});if(!r.segmento&&['conteudos','campanhas','projetos','eventos','solicitacoes'].includes(m))out.push({...r,_module:m,_quality:`${label} sem segmento`,_severity:'MÉDIA'});if(m==='campanhas'&&!String(r.objetivo||r.descricao||'').trim())out.push({...r,_module:m,_quality:'Campanha sem objetivo',_severity:'ALTA'});if(m==='conteudos'&&!String(r.legenda||r.descricao||r.objetivo||'').trim())out.push({...r,_module:m,_quality:'Conteúdo sem briefing/texto',_severity:'MÉDIA'});if(['projetos','eventos'].includes(m)&&!String(r.objetivo||r.descricao||'').trim())out.push({...r,_module:m,_quality:`${label} sem objetivo/descrição`,_severity:'BAIXA'});if(r.arquivoEstado==='FINAL'&&!String(r.arquivoFinal||r.arquivoAtual||'').trim())out.push({...r,_module:m,_quality:'Arquivo FINAL sem referência',_severity:'ALTA'});})) ;(data.campanhas||[]).filter(r=>!/CONCLU|CANCEL|ARQUIV/i.test(r.status||'')).forEach(c=>{const linked=(data.conteudos||[]).some(x=>String(x.campanhaId||'')===String(c.id||''));if(c.id&&!linked)out.push({...c,_module:'campanhas',_quality:'Campanha ativa sem conteúdo vinculado',_severity:'MÉDIA'})});return out}
function strategicSnapshot(data){const month=new Date().toISOString().slice(0,7),sp=strategyPrefs();const active=(r)=>!/CONCLU|CANCEL|ARQUIV|PUBLICADO/i.test(String(r.status||''));const monthPublished=(data.conteudos||[]).filter(r=>/PUBLICADO/i.test(r.status||'')&&currentMonth(strategyDate(r,'conteudos'))).length;const monthCampaigns=(data.campanhas||[]).filter(r=>active(r)&&(!r.dataInicio||String(r.dataInicio).slice(0,7)<=month)).length;const monthProjects=(data.projetos||[]).filter(r=>/CONCLU/i.test(r.status||'')&&currentMonth(strategyDate(r,'projetos'))).length;const monthEvents=(data.eventos||[]).filter(r=>currentMonth(strategyDate(r,'eventos'))).length;const done=[...(data.tarefas||[]),...(data.projetos||[]),...(data.solicitacoes||[])].filter(r=>isClosedRecord(r)&&recordDate(r));const onTime=done.length?Math.round(done.filter(r=>{const end=String(r.atualizadoEm||r.aprovadoSolicitanteEm||r.prazo||'').slice(0,10);return end&&end<=recordDate(r)}).length/done.length*100):100;const issues=qualityAudit(data),qualityBase=Math.max(1,['tarefas','conteudos','campanhas','projetos','eventos','solicitacoes'].reduce((a,m)=>a+(data[m]||[]).length,0)),qualityScore=Math.max(0,Math.round(100-(issues.length/qualityBase*35)));const gov=operationalSnapshot(data),criticalRisks=gov.items.filter(r=>r._risk>=70).length;const bySegment={};STRATEGIC_SEGMENTS.forEach(seg=>bySegment[seg]={conteudos:0,campanhas:0,projetos:0,eventos:0,total:0});[['conteudos','conteudos'],['campanhas','campanhas'],['projetos','projetos'],['eventos','eventos']].forEach(([m,k])=>(data[m]||[]).forEach(r=>{const seg=STRATEGIC_SEGMENTS.find(x=>personNorm(r.segmento)===personNorm(x));if(seg){bySegment[seg][k]++;bySegment[seg].total++}}));const upcoming=[];[['conteudos','publicacaoEm'],['campanhas','dataInicio'],['eventos','dataInicio'],['projetos','prazo']].forEach(([m,key])=>(data[m]||[]).forEach(r=>{const dt=String(r[key]||'').slice(0,10),d=daysUntil(dt);if(dt&&d>=0&&d<=30)upcoming.push({...r,_module:m,_date:dt})}));upcoming.sort((a,b)=>a._date.localeCompare(b._date));return {monthPublished,monthCampaigns,monthProjects,monthEvents,onTime,qualityIssues:issues,qualityScore,criticalRisks,bySegment,upcoming,sp}}
function strategicGoalCard(label,value,target,suffix=''){const p=Math.min(100,Math.round((Number(value)||0)/Math.max(1,Number(target)||1)*100));return `<div class="strategy-goal"><div><span>${esc(label)}</span><b>${esc(value)}${suffix} / ${esc(target)}${suffix}</b></div><div class="strategy-progress"><i style="width:${p}%"></i></div><small>${p}% da meta</small></div>`}
function exportStrategyCSV(snap){const rows=[['Indicador','Atual','Meta'],['Conteúdos publicados',snap.monthPublished,snap.sp.goals.contents],['Campanhas ativas',snap.monthCampaigns,snap.sp.goals.campaigns],['Projetos concluídos',snap.monthProjects,snap.sp.goals.projects],['Eventos no mês',snap.monthEvents,snap.sp.goals.events],['Pontualidade',snap.onTime+'%',snap.sp.goals.onTime+'%'],['Qualidade',snap.qualityScore+'%',snap.sp.goals.quality+'%'],[],['Pendências de qualidade','Módulo','Responsável'],...snap.qualityIssues.map(x=>[x._quality,MODULES[x._module]?.label||x._module,x.responsavel||''])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');downloadText(`EVO_MKT_ESTRATEGIA_${today()}.csv`,csv,'text/csv;charset=utf-8')}
function strategyDecisions(){return pref('strategyDecisions',[])}
function addStrategyDecision(){const text=prompt('Decisão estratégica / direcionamento:','');if(!text?.trim())return;const owner=prompt('Responsável pela decisão/ação:',internalSession?.name||'Natália Mello')||'';const due=prompt('Prazo da ação (AAAA-MM-DD, opcional):','')||'';const list=strategyDecisions();list.unshift({text:text.trim(),owner:owner.trim(),due:due.trim(),em:new Date().toISOString()});setPref('strategyDecisions',list.slice(0,50));renderStrategy()}
async function renderStrategy(){if(internalSession?.role!=='manager')return go('minhaarea');const data=await allData(['equipe','tarefas','projetos','conteudos','solicitacoes','eventos','campanhas','agenda']);const snap=strategicSnapshot(data),sp=snap.sp,maxSeg=Math.max(1,...Object.values(snap.bySegment).map(x=>x.total));$('#content').innerHTML=`<div class="dashboard-head"><div><small>PLANEJAMENTO ESTRATÉGICO</small><h1>Estratégia</h1><p>Metas, equilíbrio por segmento, qualidade dos registros e próximos movimentos do Marketing.</p></div><div><button class="softbtn" id="strategyExport">Exportar CSV</button><button class="btn" id="strategyConfig">Configurar metas</button></div></div><div class="strategy-focus"><small>FOCO DO PERÍODO</small><strong>${esc(sp.focus)}</strong><button class="softbtn" id="strategyFocus">Editar foco</button></div><div class="kpis"><div class="kpi ${snap.qualityScore>=sp.goals.quality?'green':'orange'}"><small>Qualidade</small><strong>${snap.qualityScore}%</strong></div><div class="kpi ${snap.onTime>=sp.goals.onTime?'green':'orange'}"><small>Pontualidade</small><strong>${snap.onTime}%</strong></div><div class="kpi red"><small>Riscos críticos</small><strong>${snap.criticalRisks}</strong></div><div class="kpi"><small>Pendências de qualidade</small><strong>${snap.qualityIssues.length}</strong></div></div><div class="strategy-grid"><div class="card span2"><div class="card-title"><div><small>METAS DO MÊS</small><h3>Planejado × realizado</h3></div></div>${strategicGoalCard('Conteúdos publicados',snap.monthPublished,sp.goals.contents)}${strategicGoalCard('Campanhas ativas',snap.monthCampaigns,sp.goals.campaigns)}${strategicGoalCard('Projetos concluídos',snap.monthProjects,sp.goals.projects)}${strategicGoalCard('Eventos',snap.monthEvents,sp.goals.events)}${strategicGoalCard('Pontualidade',snap.onTime,sp.goals.onTime,'%')}${strategicGoalCard('Qualidade',snap.qualityScore,sp.goals.quality,'%')}</div><div class="card"><div class="card-title"><div><small>EQUILÍBRIO</small><h3>Por segmento</h3></div></div>${Object.entries(snap.bySegment).map(([seg,x])=>`<div class="segment-strategy"><span>${esc(seg)}</span><div><i style="width:${Math.max(4,x.total/maxSeg*100)}%"></i></div><b>${x.total}</b><small>${x.conteudos} cont. · ${x.campanhas} camp. · ${x.projetos} proj. · ${x.eventos} evt.</small></div>`).join('')}</div><div class="card"><div class="card-title"><div><small>PRÓXIMOS 30 DIAS</small><h3>Agenda estratégica</h3></div><button class="softbtn" data-go="calendario">Calendário</button></div>${snap.upcoming.slice(0,8).map(r=>`<button class="strategy-upcoming" data-go="${r._module}"><time>${fmtDate(r._date)}</time><div><b>${esc(r.titulo||MODULES[r._module].label)}</b><small>${esc(MODULES[r._module].label)} · ${esc(r.segmento||'Geral')}</small></div></button>`).join('')||'<div class="empty compact">Nenhum marco nos próximos 30 dias.</div>'}</div><div class="card span2"><div class="card-title"><div><small>QUALIDADE OPERACIONAL</small><h3>Registros que precisam ser completados</h3></div><span class="quality-score">${snap.qualityScore}%</span></div>${snap.qualityIssues.slice(0,14).map(q=>`<button class="quality-row" data-go="${q._module}"><span class="quality-severity ${q._severity.toLowerCase()}">${esc(q._severity)}</span><div><b>${esc(q.titulo||'(sem título)')}</b><small>${esc(q._quality)} · ${esc(q.responsavel||'Sem responsável')}</small></div></button>`).join('')||'<div class="empty compact">Nenhuma inconsistência relevante encontrada.</div>'}</div><div class="card span2"><div class="card-title"><div><small>DECISÕES</small><h3>Registro estratégico</h3></div><button class="softbtn" id="strategyDecisionAdd">+ Decisão</button></div><div class="strategy-decisions">${strategyDecisions().slice(0,8).map(x=>`<div class="strategy-decision"><span>◆</span><div><b>${esc(x.text)}</b><small>${esc(x.owner||'Sem responsável')}${x.due?` · prazo ${fmtDate(x.due)}`:''} · ${fmtDateTime(x.em)}</small></div></div>`).join('')||'<div class="empty compact">Nenhuma decisão registrada.</div>'}</div></div><div class="card span2"><div class="card-title"><div><small>REVISÃO SEMANAL</small><h3>Registro executivo</h3></div><button class="softbtn" id="weeklyReviewEdit">Atualizar</button></div><div class="weekly-review">${sp.weeklyReview?esc(sp.weeklyReview):'Nenhuma revisão semanal registrada. Use este espaço para decisões, prioridades e aprendizados da semana.'}</div></div></div>`;$('#strategyConfig').onclick=()=>{const c=Number(prompt('Meta mensal de conteúdos publicados:',sp.goals.contents));if(!Number.isFinite(c)||c<0)return;const ca=Number(prompt('Meta de campanhas ativas:',sp.goals.campaigns));const pr=Number(prompt('Meta de projetos concluídos:',sp.goals.projects));const ev=Number(prompt('Meta de eventos no mês:',sp.goals.events));const ot=Number(prompt('Meta de pontualidade (%):',sp.goals.onTime));const qu=Number(prompt('Meta de qualidade (%):',sp.goals.quality));saveStrategyPrefs({...sp,goals:{contents:c,campaigns:Number.isFinite(ca)?ca:sp.goals.campaigns,projects:Number.isFinite(pr)?pr:sp.goals.projects,events:Number.isFinite(ev)?ev:sp.goals.events,onTime:Number.isFinite(ot)?ot:sp.goals.onTime,quality:Number.isFinite(qu)?qu:sp.goals.quality}});renderStrategy()};$('#strategyFocus').onclick=()=>{const v=prompt('Foco estratégico do período:',sp.focus);if(v===null)return;saveStrategyPrefs({...sp,focus:v.trim()||sp.focus});renderStrategy()};$('#weeklyReviewEdit').onclick=()=>{const v=prompt('Revisão semanal / decisões da Gerente:',sp.weeklyReview||'');if(v===null)return;saveStrategyPrefs({...sp,weeklyReview:v});renderStrategy()};$('#strategyExport').onclick=()=>exportStrategyCSV(snap);$('#strategyDecisionAdd').onclick=addStrategyDecision;bindGoButtons()}

async function renderToday(){const d=await allData(['tarefas','conteudos','eventos','campanhas','projetos','aprovacoes','equipe','solicitacoes']);const t=today(),next=new Date();next.setDate(next.getDate()+7);const n7=isoDate(next);const overdue=d.tarefas.filter(r=>r.prazo&&r.prazo<t&&!/CONCLU|CANCEL/i.test(r.status||''));const todayTasks=d.tarefas.filter(r=>r.prazo===t);const todayContent=d.conteudos.filter(r=>(r.publicacaoEm||'').slice(0,10)===t);const approvals=d.aprovacoes.filter(r=>/AGUARDANDO/i.test(r.status||r.tipoAprovacao||''));const events=d.eventos.filter(r=>{const x=(r.dataInicio||'').slice(0,10);return x>=t&&x<=n7});const recent=pref('recent',[]).filter(x=>MODULES[x]);const fav=pref('favorites',[]).filter(x=>MODULES[x]);const govToday=operationalSnapshot(d),riskToday=govToday.items.filter(r=>r._risk>=governancePrefs().alertThreshold&&daysUntil(recordDate(r))>=0);const alertCount=overdue.length+approvals.length+riskToday.length;setPref('alertCount',alertCount);updateHeader();$('#content').innerHTML=`<div class="today-banner"><div><small>HOJE NO MARKETING</small><h1>${new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date())}</h1><p>O que precisa da sua atenção antes de abrir qualquer módulo.</p></div><div class="today-score"><span>Itens de atenção</span><strong>${alertCount}</strong></div></div><div class="kpis"><div class="kpi red"><small>Tarefas atrasadas</small><strong>${overdue.length}</strong></div><div class="kpi orange"><small>Para hoje</small><strong>${todayTasks.length+todayContent.length}</strong></div><div class="kpi"><small>Aprovações</small><strong>${approvals.length}</strong></div><div class="kpi green"><small>Eventos em 7 dias</small><strong>${events.length}</strong></div></div><div class="dashboard-grid"><div class="card span2"><div class="card-title"><div><small>PRIORIDADES</small><h3>O que fazer agora</h3></div><button class="softbtn" data-go="central">Central Operacional</button></div>${[...overdue,...todayTasks,...riskToday.filter(r=>r._module==='tarefas')].filter((r,i,a)=>a.findIndex(x=>x.id===r.id)===i).slice(0,8).map(r=>`<div class="task-line"><span class="urgency ${r.prazo<t?'late':'today'}"></span><div><b>${esc(r.titulo)}</b><small>${esc(r.responsavel||'Sem responsável')} · ${esc(r.prioridade||'Sem prioridade')}${r._risk?' · risco '+r._risk:''}</small></div><time>${fmtDate(r.prazo)}</time></div>`).join('')||'<div class="empty compact"><strong>Nada crítico agora</strong><span>As prioridades de hoje aparecerão aqui.</span></div>'}</div><div class="card"><div class="card-title"><div><small>PRÓXIMOS</small><h3>Eventos</h3></div></div>${events.slice(0,5).map(r=>`<div class="mini-event"><b>${fmtDate(r.dataInicio)}</b><span>${esc(r.titulo)}</span></div>`).join('')||'<div class="empty compact">Sem eventos próximos.</div>'}</div><div class="card"><div class="card-title"><div><small>ATALHOS</small><h3>Acesso rápido</h3></div></div><div class="quick-grid">${(fav.length?fav:['tarefas','conteudos','calendario','trafego']).slice(0,6).map(p=>`<button data-go="${p}"><span>${MODULES[p].icon}</span>${esc(MODULES[p].label)}</button>`).join('')}</div></div><div class="card"><div class="card-title"><div><small>RECENTES</small><h3>Últimos módulos</h3></div></div><div class="recent-list">${recent.slice(0,5).map(p=>`<button data-go="${p}">${MODULES[p].icon}<span>${esc(MODULES[p].label)}</span></button>`).join('')||'<span class="soft-note">Conforme você navegar, os módulos recentes aparecerão aqui.</span>'}</div></div></div>`;bindGoButtons()}
async function renderDashboard(){const d=await allData(['tarefas','conteudos','eventos','campanhas','projetos','aprovacoes','trafego','instagram','equipe','solicitacoes']);const invest=d.trafego.reduce((a,r)=>a+num(r.investimento),0),conv=d.trafego.reduce((a,r)=>a+num(r.conversas),0),leads=d.trafego.reduce((a,r)=>a+num(r.leads),0),published=d.conteudos.filter(r=>/PUBLICADO/i.test(r.status||'')).length,activeProj=d.projetos.filter(r=>!/CONCLU|ARQUIV/i.test(r.status||'')).length;const govSnap=operationalSnapshot(d),govCritical=govSnap.items.filter(r=>r._risk>=70).length,govOverload=govSnap.people.filter(p=>p.load>=90).length,stratSnap=strategicSnapshot(d),editSnap=editorialSnapshot(d),closeSnap=closingSnapshot(d,new Date().toISOString().slice(0,7));const widgets=pref('widgets',{traffic:true,content:true,projects:true,activity:true});$('#content').innerHTML=`<div class="dashboard-head"><div><small>PAINEL EXECUTIVO</small><h1>Dashboard</h1><p>Indicadores consolidados dos arquivos XLSX locais.</p></div><button class="softbtn" id="widgetConfig">Configurar widgets</button></div><div class="kpis"><div class="kpi"><small>Investimento</small><strong>${money(invest)}</strong></div><div class="kpi orange"><small>Conversas</small><strong>${conv}</strong></div><div class="kpi green"><small>Leads</small><strong>${leads}</strong></div><div class="kpi"><small>Projetos ativos</small><strong>${activeProj}</strong></div></div><div class="dashboard-grid">${widgets.traffic?`<div class="card span2"><div class="card-title"><div><small>TRÁFEGO</small><h3>Funil acumulado</h3></div><button data-go="trafego" class="softbtn">Abrir tráfego</button></div><div class="funnel large"><div><span>Investimento</span><strong>${money(invest)}</strong></div><div><span>Conversas</span><strong>${conv}</strong></div><div><span>Leads</span><strong>${leads}</strong></div><div><span>Custo/lead</span><strong>${money(invest/Math.max(1,leads))}</strong></div></div></div>`:''}${widgets.content?`<div class="card"><div class="card-title"><div><small>CONTEÚDO</small><h3>Produção</h3></div></div><div class="big-number">${published}</div><p>conteúdos publicados · ${d.aprovacoes.filter(r=>/AGUARDANDO/i.test(r.status||'')).length} aguardando aprovação</p></div>`:''}${widgets.projects?`<div class="card"><div class="card-title"><div><small>PROJETOS</small><h3>Andamento</h3></div></div>${d.projetos.slice(0,5).map(r=>{const p=Math.min(100,num(r.progresso));return `<div class="dash-progress"><span>${esc(r.titulo)}</span><div><i style="width:${p}%"></i></div><b>${p}%</b></div>`}).join('')||'<div class="empty compact">Nenhum projeto cadastrado.</div>'}</div>`:''}<div class="card strategy-mini"><div class="card-title"><div><small>ESTRATÉGIA</small><h3>Qualidade e pontualidade</h3></div><button data-go="estrategia" class="softbtn">Abrir</button></div><div class="personal-breakdown"><div><span>Qualidade</span><b>${stratSnap.qualityScore}%</b></div><div><span>Pontualidade</span><b>${stratSnap.onTime}%</b></div></div></div><div class="card governance-mini"><div class="card-title"><div><small>GOVERNANÇA</small><h3>Risco operacional</h3></div><button data-go="governanca" class="softbtn">Abrir</button></div><div class="personal-breakdown"><div><span>Críticos</span><b>${govCritical}</b></div><div><span>Sobrecarregados</span><b>${govOverload}</b></div></div></div><div class="card editorial-mini"><div class="card-title"><div><small>EDITORIAL</small><h3>Próximos conteúdos</h3></div><button data-go="editorial" class="softbtn">Abrir</button></div><div class="personal-breakdown"><div><span>30 dias</span><b>${editSnap.scheduled.length}</b></div><div><span>Campanhas descobertas</span><b>${editSnap.campaignRows.filter(x=>x._coverage==='CRÍTICO').length}</b></div></div></div><div class="card closing-mini"><div class="card-title"><div><small>FECHAMENTO</small><h3>Mês atual</h3></div><button data-go="fechamento" class="softbtn">Abrir</button></div><div class="personal-breakdown"><div><span>Concluídos</span><b>${closeSnap.published+closeSnap.doneProjects+closeSnap.doneTasks+closeSnap.doneReq}</b></div><div><span>Pendências</span><b>${closeSnap.open.length}</b></div></div></div>${widgets.activity?`<div class="card span2"><div class="card-title"><div><small>OPERAÇÃO</small><h3>Volume por módulo</h3></div></div><div class="bar-list">${[['Tarefas',d.tarefas.length],['Conteúdos',d.conteudos.length],['Eventos',d.eventos.length],['Campanhas',d.campanhas.length],['Aprovações',d.aprovacoes.length]].map(([l,v])=>`<div><span>${l}</span><div><i style="width:${Math.min(100,v*10)}%"></i></div><b>${v}</b></div>`).join('')}</div></div>`:''}</div>`;bindGoButtons();$('#widgetConfig').onclick=()=>configureWidgets()}
function configureWidgets(){const w=pref('widgets',{traffic:true,content:true,projects:true,activity:true});const names={traffic:'Tráfego',content:'Conteúdo',projects:'Projetos',activity:'Operação'};const msg=Object.keys(names).map((k,i)=>`${i+1}. ${names[k]}: ${w[k]?'visível':'oculto'}`).join('\n');const n=prompt(`Digite o número do widget para alternar:\n\n${msg}`);const key=Object.keys(names)[Number(n)-1];if(key){w[key]=!w[key];setPref('widgets',w);renderDashboard()}}
async function renderCentral(){const d=await allData(['tarefas','conteudos','eventos','campanhas','projetos','aprovacoes','equipe','solicitacoes']);const t=today();const alerts=[];const govSnap=operationalSnapshot(d);d.tarefas.forEach(r=>{if(r.prazo&&r.prazo<t&&!/CONCLU|CANCEL/i.test(r.status||''))alerts.push({...r,_m:'tarefas',_why:'Tarefa atrasada'});if(!r.responsavel)alerts.push({...r,_m:'tarefas',_why:'Sem responsável'})});d.conteudos.forEach(r=>{if(!r.publicacaoEm&&!/PUBLICADO|ARQUIV/i.test(r.status||''))alerts.push({...r,_m:'conteudos',_why:'Conteúdo sem data'});if(!r.responsavel)alerts.push({...r,_m:'conteudos',_why:'Sem responsável'})});d.aprovacoes.filter(r=>/AGUARDANDO/i.test(r.status||r.tipoAprovacao||'')).forEach(r=>alerts.push({...r,_m:'aprovacoes',_why:'Aguardando aprovação'}));d.solicitacoes.filter(r=>/AGUARDANDO TRIAGEM|NOVA/i.test((r.triagemStatus||'')+' '+(r.status||''))).forEach(r=>alerts.push({...r,_m:'solicitacoes',_why:'Nova demanda aguardando triagem'}));d.projetos.filter(r=>/RISCO|PAUSADO/i.test(r.status||'')).forEach(r=>alerts.push({...r,_m:'projetos',_why:'Projeto precisa de atenção'}));govSnap.items.filter(r=>r._risk>=governancePrefs().alertThreshold&&daysUntil(recordDate(r))>=0).slice(0,8).forEach(r=>alerts.push({...r,_m:r._module,_why:`Risco preventivo ${riskLevel(r._risk)} · score ${r._risk}`}));qualityAudit(d).filter(q=>q._severity==='ALTA').slice(0,5).forEach(q=>alerts.push({...q,_m:q._module,_why:`Qualidade: ${q._quality}`}));const ed=editorialSnapshot(d);ed.editorialIssues.slice(0,4).forEach(q=>alerts.push({...q,_m:'conteudos',_why:`Editorial: ${q._issues.join(' · ')}`}));ed.campaignRows.filter(c=>c._coverage==='CRÍTICO'||c._coverage==='ATENÇÃO').slice(0,4).forEach(c=>alerts.push({...c,_m:'campanhas',_why:`Cobertura editorial: ${c._coverage} · ${c._linked} conteúdo(s)`}));const workload={};d.tarefas.filter(r=>!/CONCLU|CANCEL/i.test(r.status||'')).forEach(r=>{const n=r.responsavel||'Sem responsável';workload[n]=(workload[n]||0)+1});const timeline=[...Object.entries(d).flatMap(([m,rs])=>rs.map(r=>({...r,_m:m})))].filter(r=>r.atualizadoEm).sort((a,b)=>String(b.atualizadoEm).localeCompare(String(a.atualizadoEm))).slice(0,12);setPref('alertCount',alerts.length);updateHeader();$('#content').innerHTML=`<div class="dashboard-head"><div><small>CENTRAL OPERACIONAL</small><h1>O que precisa de atenção</h1><p>Pendências derivadas automaticamente dos registros locais.</p></div><span class="alert-pill">${alerts.length} alerta(s)</span></div><div class="dashboard-grid"><div class="card span2"><div class="card-title"><div><small>PENDÊNCIAS</small><h3>Fila operacional</h3></div></div>${alerts.slice(0,15).map(a=>`<button class="alert-row" data-go="${a._m}"><span class="alert-dot"></span><div><b>${esc(a.titulo||'(sem título)')}</b><small>${esc(a._why)} · ${esc(MODULES[a._m].label)}</small></div><time>${fmtDate(a.prazo||a.publicacaoEm||a.dataInicio)}</time></button>`).join('')||'<div class="empty compact">Nenhuma pendência detectada.</div>'}</div><div class="card"><div class="card-title"><div><small>CARGA</small><h3>Equipe</h3></div></div>${Object.entries(workload).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([n,v])=>`<div class="workload"><span>${esc(n)}</span><div><i style="width:${Math.min(100,v*12)}%"></i></div><b>${v}</b></div>`).join('')||'<div class="empty compact">Sem tarefas ativas.</div>'}</div><div class="card"><div class="card-title"><div><small>TIMELINE</small><h3>Atividade recente</h3></div></div>${timeline.map(r=>`<div class="timeline-row"><span>${MODULES[r._m]?.icon||'•'}</span><div><b>${esc(r.titulo||'(sem título)')}</b><small>${esc(MODULES[r._m]?.label||r._m)} · ${fmtDateTime(r.atualizadoEm)}</small></div></div>`).join('')||'<div class="empty compact">Sem atividade recente.</div>'}</div></div>`;bindGoButtons()}
function bindGoButtons(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go))}



// v3.6.0 — planejamento editorial, campanhas executivas e fechamento mensal
const EDITORIAL_FORMATS=['Feed','Carrossel','Stories','Reels','Vídeo','Foto','Outro'];
function editorialPrefs(){return pref('editorial',{targetPerWeek:5,targetReels:4,targetStories:12,targetCampaignCoverage:3})}
function saveEditorialPrefs(v){setPref('editorial',v)}

function editorialSnapshot(data){
 const now=new Date(),month=now.toISOString().slice(0,7),next30=new Date(now);next30.setDate(now.getDate()+30);
 const contents=(data.conteudos||[]), campaigns=(data.campanhas||[]), events=(data.eventos||[]), ep=editorialPrefs();
 const monthContents=contents.filter(r=>monthKey(r.publicacaoEm||r.prazo||r.dataInicio||r.criadoEm)===month);
 const scheduled=contents.filter(r=>{const d=String(r.publicacaoEm||'').slice(0,10);if(!d)return false;const x=new Date(d+'T12:00:00');return x>=new Date(today()+'T00:00:00')&&x<=next30});
 const byFormat={};EDITORIAL_FORMATS.forEach(f=>byFormat[f]=0);monthContents.forEach(r=>{const f=EDITORIAL_FORMATS.find(x=>personNorm(x)===personNorm(r.formato||''))||'Outro';byFormat[f]=(byFormat[f]||0)+1});
 const byProfile={};['@evolucaopb','@geracaoevolucao','Ambos'].forEach(p=>byProfile[p]=0);monthContents.forEach(r=>{const p=r.perfil||'Sem perfil';byProfile[p]=(byProfile[p]||0)+1});
 const bySegment={};STRATEGIC_SEGMENTS.forEach(seg=>bySegment[seg]=0);monthContents.forEach(r=>{const seg=STRATEGIC_SEGMENTS.find(x=>personNorm(x)===personNorm(r.segmento||''));if(seg)bySegment[seg]++});
 const activeCampaigns=campaigns.filter(r=>!/CONCLU|CANCEL|ARQUIV/i.test(String(r.status||'')));
 const campaignRows=activeCampaigns.map(c=>{const linked=contents.filter(x=>String(x.campanhaId||'')===String(c.id||''));const scheduledCount=linked.filter(x=>x.publicacaoEm).length;const formats=[...new Set(linked.map(x=>x.formato).filter(Boolean))];const risk=linked.length===0?'CRÍTICO':linked.length<ep.targetCampaignCoverage?'ATENÇÃO':scheduledCount<linked.length?'PENDENTE':'OK';return {...c,_linked:linked.length,_scheduled:scheduledCount,_formats:formats,_coverage:risk}});
 const unlinked=monthContents.filter(r=>!r.campanhaId&&!r.projetoId&&!r.eventoId);
 const editorialIssues=contents.filter(r=>!/PUBLICADO|ARQUIV/i.test(String(r.status||''))).flatMap(r=>{const a=[];if(!r.publicacaoEm)a.push('sem data de publicação');if(!r.perfil)a.push('sem perfil');if(!r.formato)a.push('sem formato');if(!r.segmento)a.push('sem segmento');return a.length?[{...r,_issues:a}]:[]});
 const dueEvents=events.filter(r=>{const d=String(r.dataInicio||r.prazo||'').slice(0,10);if(!d)return false;const dd=daysUntil(d);return dd>=0&&dd<=30});
 return {month,monthContents,scheduled,byFormat,byProfile,bySegment,campaignRows,unlinked,editorialIssues,dueEvents,ep};
}
function editorialBar(label,val,max){const p=Math.min(100,Math.round((val/Math.max(1,max))*100));return `<div class="editorial-bar"><span>${esc(label)}</span><div><i style="width:${p}%"></i></div><b>${val}</b></div>`}
async function renderEditorialPlanning(){
 if(internalSession?.role!=='manager')return go('minhaarea');
 const data=await allData(['conteudos','campanhas','eventos','projetos']);const s=editorialSnapshot(data);const maxFmt=Math.max(1,...Object.values(s.byFormat));const maxSeg=Math.max(1,...Object.values(s.bySegment));
 const next=s.scheduled.sort((a,b)=>String(a.publicacaoEm).localeCompare(String(b.publicacaoEm))).slice(0,12);
 $('#content').innerHTML=`<div class="dashboard-head"><div><small>PLANEJAMENTO EDITORIAL</small><h1>Calendário editorial executivo</h1><p>Conteúdos, campanhas, formatos, perfis e cobertura por segmento em uma única visão.</p></div><div><button class="softbtn" id="editorialCsv">Exportar CSV</button><button class="btn" id="editorialConfig">Metas editoriais</button></div></div>
 <div class="kpis"><div class="kpi"><small>Conteúdos no mês</small><strong>${s.monthContents.length}</strong></div><div class="kpi orange"><small>Próximos 30 dias</small><strong>${s.scheduled.length}</strong></div><div class="kpi ${s.campaignRows.some(x=>x._coverage==='CRÍTICO')?'red':'green'}"><small>Campanhas sem cobertura</small><strong>${s.campaignRows.filter(x=>x._coverage==='CRÍTICO').length}</strong></div><div class="kpi"><small>Conteúdos sem vínculo</small><strong>${s.unlinked.length}</strong></div></div>
 <div class="editorial-grid"><section class="card"><div class="card-title"><div><small>MIX EDITORIAL</small><h3>Formatos no mês</h3></div></div>${Object.entries(s.byFormat).map(([k,v])=>editorialBar(k,v,maxFmt)).join('')}</section>
 <section class="card"><div class="card-title"><div><small>COBERTURA</small><h3>Por segmento</h3></div></div>${Object.entries(s.bySegment).map(([k,v])=>editorialBar(k,v,maxSeg)).join('')}</section>
 <section class="card span2"><div class="card-title"><div><small>CAMPANHAS</small><h3>Cobertura editorial por campanha</h3></div><button class="softbtn" data-go="campanhas">Abrir Campanhas</button></div>${s.campaignRows.map(c=>`<button class="campaign-coverage" data-go="campanhas"><span class="coverage-pill ${c._coverage.toLowerCase()}">${esc(c._coverage)}</span><div><b>${esc(c.titulo||'Campanha')}</b><small>${c._linked} conteúdo(s) · ${c._scheduled} programado(s) · ${esc(c._formats.join(', ')||'sem formatos')}</small></div><time>${fmtDate(c.periodoFim||c.prazo)}</time></button>`).join('')||'<div class="empty compact">Nenhuma campanha ativa.</div>'}</section>
 <section class="card span2"><div class="card-title"><div><small>PRÓXIMOS 30 DIAS</small><h3>Publicações programadas</h3></div><button class="softbtn" data-go="calendario">Calendário</button></div>${next.map(r=>`<button class="editorial-next" data-go="conteudos"><time>${fmtDate(r.publicacaoEm)}</time><div><b>${esc(r.titulo||'Conteúdo')}</b><small>${esc(r.formato||'Formato não definido')} · ${esc(r.perfil||'Sem perfil')} · ${esc(r.segmento||'Geral')}</small></div><span>${esc(r.status||'')}</span></button>`).join('')||'<div class="empty compact">Nenhum conteúdo programado para os próximos 30 dias.</div>'}</section>
 <section class="card"><div class="card-title"><div><small>PERFIS</small><h3>Distribuição</h3></div></div>${Object.entries(s.byProfile).map(([k,v])=>`<div class="goal-line"><span>${esc(k)}</span><b>${v}</b></div>`).join('')}</section>
 <section class="card"><div class="card-title"><div><small>OPORTUNIDADES</small><h3>Eventos próximos</h3></div></div>${s.dueEvents.slice(0,8).map(e=>`<button class="strategy-upcoming" data-go="eventos"><time>${fmtDate(e.dataInicio||e.prazo)}</time><div><b>${esc(e.titulo||'Evento')}</b><small>${esc(e.segmento||'Geral')}</small></div></button>`).join('')||'<div class="empty compact">Nenhum evento próximo.</div>'}</section><section class="card span2"><div class="card-title"><div><small>QUALIDADE EDITORIAL</small><h3>Conteúdos incompletos</h3></div><span class="alert-pill">${s.editorialIssues.length}</span></div>${s.editorialIssues.slice(0,12).map(r=>`<button class="quality-row" data-go="conteudos"><span class="quality-severity média">ATENÇÃO</span><div><b>${esc(r.titulo||'(sem título)')}</b><small>${esc(r._issues.join(' · '))}</small></div></button>`).join('')||'<div class="empty compact">Planejamento editorial completo.</div>'}</section></div>`;
 $('#editorialCsv').onclick=()=>exportCSV('PLANEJAMENTO_EDITORIAL',s.monthContents.map(r=>({titulo:r.titulo,formato:r.formato,perfil:r.perfil,segmento:r.segmento,status:r.status,publicacao:r.publicacaoEm,campanhaId:r.campanhaId})));$('#editorialConfig').onclick=()=>{const w=Number(prompt('Meta de conteúdos por semana:',s.ep.targetPerWeek));if(!Number.isFinite(w)||w<0)return;const reels=Number(prompt('Meta mensal de Reels:',s.ep.targetReels));const stories=Number(prompt('Meta mensal de Stories:',s.ep.targetStories));const cov=Number(prompt('Cobertura mínima de conteúdos por campanha:',s.ep.targetCampaignCoverage));saveEditorialPrefs({targetPerWeek:w,targetReels:Number.isFinite(reels)?reels:s.ep.targetReels,targetStories:Number.isFinite(stories)?stories:s.ep.targetStories,targetCampaignCoverage:Number.isFinite(cov)?cov:s.ep.targetCampaignCoverage});renderEditorialPlanning()};bindGoButtons();
}
function closingPrefs(){return pref('closing',{notes:'',nextFocus:'',lastMonth:''})}
function saveClosingPrefs(v){setPref('closing',v)}
function closingSnapshot(data,month){const contents=(data.conteudos||[]).filter(r=>monthKey(r.publicacaoEm||r.atualizadoEm||r.prazo)===month).map(r=>({...r,_module:'conteudos'})),campaigns=(data.campanhas||[]).filter(r=>monthKey(r.dataInicio||r.atualizadoEm)===month).map(r=>({...r,_module:'campanhas'})),projects=(data.projetos||[]).filter(r=>monthKey(r.atualizadoEm||r.prazo||r.dataInicio)===month).map(r=>({...r,_module:'projetos'})),events=(data.eventos||[]).filter(r=>monthKey(r.dataInicio||r.prazo)===month).map(r=>({...r,_module:'eventos'})),tasks=(data.tarefas||[]).filter(r=>monthKey(r.atualizadoEm||r.prazo||r.dataInicio)===month).map(r=>({...r,_module:'tarefas'})),requests=(data.solicitacoes||[]).filter(r=>monthKey(r.criadoEm||r.dataInicio||r.prazo)===month).map(r=>({...r,_module:'solicitacoes'}));const published=contents.filter(r=>/PUBLICADO/i.test(r.status||'')).length,doneProjects=projects.filter(isClosedRecord).length,doneTasks=tasks.filter(isClosedRecord).length,doneReq=requests.filter(isClosedRecord).length,open=[...tasks,...projects,...requests].filter(r=>!isClosedRecord(r));const late=open.filter(r=>daysUntil(recordDate(r))<0).length;const topSegments={};[...contents,...campaigns,...events,...projects].forEach(r=>{const s=r.segmento||'Sem segmento';topSegments[s]=(topSegments[s]||0)+1});return {contents,campaigns,projects,events,tasks,requests,published,doneProjects,doneTasks,doneReq,open,late,topSegments}}
function previousMonthKey(month){const [y,m]=String(month).split('-').map(Number);const d=new Date(y,m-2,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function trendBadge(now,prev,inverse=false){const diff=(Number(now)||0)-(Number(prev)||0);const good=inverse?diff<=0:diff>=0;return `<span class="trend-badge ${good?'good':'bad'}">${diff===0?'=':(diff>0?'+':'')+diff}</span>`}
async function renderMonthlyClosing(){if(internalSession?.role!=='manager')return go('minhaarea');const cp=closingPrefs();const month=cp.lastMonth||new Date().toISOString().slice(0,7);const data=await allData(['conteudos','campanhas','projetos','eventos','tarefas','solicitacoes','trafego','instagram']);const s=closingSnapshot(data,month),prev=closingSnapshot(data,previousMonthKey(month));const totalDone=s.published+s.doneProjects+s.doneTasks+s.doneReq,prevDone=prev.published+prev.doneProjects+prev.doneTasks+prev.doneReq;$('#content').innerHTML=`<div class="dashboard-head"><div><small>FECHAMENTO MENSAL</small><h1>Resumo do mês</h1><p>Realizado, pendências, aprendizados e foco do próximo ciclo.</p></div><div><input class="control" type="month" id="closingMonth" value="${attr(month)}"><button class="softbtn" id="closingCsv">CSV</button><button class="btn" id="closingPrint">Imprimir / PDF</button></div></div><div class="kpis"><div class="kpi green"><small>Entregas concluídas</small><strong>${totalDone} ${trendBadge(totalDone,prevDone)}</strong></div><div class="kpi"><small>Conteúdos publicados</small><strong>${s.published} ${trendBadge(s.published,prev.published)}</strong></div><div class="kpi orange"><small>Pendências abertas</small><strong>${s.open.length} ${trendBadge(s.open.length,prev.open.length,true)}</strong></div><div class="kpi ${s.late?'red':'green'}"><small>Atrasos</small><strong>${s.late} ${trendBadge(s.late,prev.late,true)}</strong></div></div><div class="closing-grid"><section class="card"><div class="card-title"><div><small>REALIZADO</small><h3>Produção do período</h3></div></div><div class="closing-stat"><span>Conteúdos</span><b>${s.contents.length}</b></div><div class="closing-stat"><span>Campanhas</span><b>${s.campaigns.length}</b></div><div class="closing-stat"><span>Projetos concluídos</span><b>${s.doneProjects}</b></div><div class="closing-stat"><span>Eventos</span><b>${s.events.length}</b></div><div class="closing-stat"><span>Tarefas concluídas</span><b>${s.doneTasks}</b></div><div class="closing-stat"><span>Demandas concluídas</span><b>${s.doneReq}</b></div></section><section class="card"><div class="card-title"><div><small>SEGMENTOS</small><h3>Distribuição do mês</h3></div></div>${Object.entries(s.topSegments).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="goal-line"><span>${esc(k)}</span><b>${v}</b></div>`).join('')||'<div class="empty compact">Sem registros no período.</div>'}</section><section class="card span2"><div class="card-title"><div><small>PENDÊNCIAS PARA O PRÓXIMO MÊS</small><h3>Carry-over</h3></div></div>${s.open.slice(0,15).map(r=>`<button class="closing-open" data-go="${r._module||'tarefas'}"><div><b>${esc(r.titulo||'Item')}</b><small>${esc(r.responsavel||'Sem responsável')} · ${esc(r.status||'')}</small></div><time>${fmtDate(recordDate(r))}</time></button>`).join('')||'<div class="empty compact">Nenhuma pendência relevante carregada para o próximo ciclo.</div>'}</section><section class="card"><div class="card-title"><div><small>APRENDIZADOS</small><h3>Notas do fechamento</h3></div><button class="softbtn" id="closingNotes">Editar</button></div><div class="weekly-review">${cp.notes?esc(cp.notes):'Registre aprendizados, pontos fortes e ajustes necessários.'}</div></section><section class="card"><div class="card-title"><div><small>PRÓXIMO CICLO</small><h3>Foco do próximo mês</h3></div><button class="softbtn" id="closingFocus">Editar</button></div><div class="weekly-review">${cp.nextFocus?esc(cp.nextFocus):'Defina o principal foco do próximo mês.'}</div></section></div>`;$('#closingMonth').onchange=e=>{saveClosingPrefs({...cp,lastMonth:e.target.value});renderMonthlyClosing()};$('#closingCsv').onclick=()=>exportCSV('FECHAMENTO_'+month,[{mes:month,entregas:totalDone,conteudosPublicados:s.published,campanhas:s.campaigns.length,projetosConcluidos:s.doneProjects,eventos:s.events.length,tarefasConcluidas:s.doneTasks,demandasConcluidas:s.doneReq,pendencias:s.open.length,atrasos:s.late}]);$('#closingPrint').onclick=()=>window.print();$('#closingNotes').onclick=()=>{const v=prompt('Aprendizados do fechamento:',cp.notes||'');if(v===null)return;saveClosingPrefs({...cp,notes:v});renderMonthlyClosing()};$('#closingFocus').onclick=()=>{const v=prompt('Foco do próximo mês:',cp.nextFocus||'');if(v===null)return;saveClosingPrefs({...cp,nextFocus:v});renderMonthlyClosing()};bindGoButtons()}

async function renderCalendar(){const mods=['agenda','tarefas','eventos','conteudos','campanhas','calendario'];const d=await allData(mods);const items=[];mods.forEach(m=>d[m].forEach(r=>{const rd=rowDate(r,m);if(rd.value)items.push({...r,_m:m,_key:rd.key,_date:String(rd.value).slice(0,10)})}));const date=state.calendarDate;const label=new Intl.DateTimeFormat('pt-BR',state.calendarMode==='month'?{month:'long',year:'numeric'}:{day:'2-digit',month:'long',year:'numeric'}).format(date);setTitle('Calendário',label);let body='';if(state.calendarMode==='month')body=calendarMonth(items,date);else if(state.calendarMode==='week')body=calendarWeek(items,date);else body=calendarDay(items,date);$('#content').innerHTML=`<div class="calendar-head"><div><small>PLANEJAMENTO</small><h1>Calendário</h1><p>Agenda, tarefas, eventos, conteúdos e campanhas em uma única linha do tempo. Clique em qualquer espaço livre para criar.</p></div><div class="calendar-controls"><button class="btn" id="calNew">+ Novo item</button><button class="softbtn" id="calPrev">‹</button><button class="softbtn" id="calToday">Hoje</button><button class="softbtn" id="calNext">›</button><div class="view-switch"><button data-cal="day" class="${state.calendarMode==='day'?'active':''}">Dia</button><button data-cal="week" class="${state.calendarMode==='week'?'active':''}">Semana</button><button data-cal="month" class="${state.calendarMode==='month'?'active':''}">Mês</button></div></div></div><div class="calendar-title">${esc(label)}</div>${body}<div class="calendar-legend">${mods.map(m=>`<span><i class="cal-color ${m}"></i>${esc(MODULES[m].label)}</span>`).join('')}</div>`;bindCalendar(items)}
function calendarMonth(items,date){const y=date.getFullYear(),mo=date.getMonth(),first=new Date(y,mo,1),start=new Date(y,mo,1-first.getDay());let h=`<div class="calendar month">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(x=>`<div class="dayhead">${x}</div>`).join('')}`;for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=isoDate(d),ev=items.filter(x=>x._date===key).slice(0,4);h+=`<div class="day cal-drop ${d.getMonth()!==mo?'muted':''} ${key===today()?'today':''}" data-date="${key}"><button class="daynum" data-date="${key}">${d.getDate()}</button>${ev.map(calendarItem).join('')}${items.filter(x=>x._date===key).length>4?`<span class="more-events">+${items.filter(x=>x._date===key).length-4}</span>`:''}</div>`}return h+'</div>'}
function calendarWeek(items,date){const d=new Date(date),sun=new Date(d);sun.setDate(d.getDate()-d.getDay());return `<div class="week-grid">${Array.from({length:7},(_,i)=>{const x=new Date(sun);x.setDate(sun.getDate()+i);const key=isoDate(x),ev=items.filter(r=>r._date===key);return `<div class="week-day cal-drop ${key===today()?'today':''}" data-date="${key}"><div class="week-date"><b>${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'][i]}</b><strong>${x.getDate()}</strong></div>${ev.map(calendarItem).join('')||'<span class="no-events">Sem itens</span>'}</div>`}).join('')}</div>`}
function calendarDay(items,date){const key=isoDate(date),ev=items.filter(r=>r._date===key);return `<div class="day-view cal-drop" data-date="${key}"><div class="day-agenda">${ev.map(calendarItem).join('')||'<div class="empty"><strong>Dia livre</strong><span>Clique em “+ Novo item” ou no espaço do calendário para criar.</span></div>'}</div></div>`}
function calendarItem(r){return `<button class="cal-item ${r._m}" draggable="true" data-id="${attr(r.id)}" data-module="${r._m}" title="${attr(r.titulo)}"><span>${MODULES[r._m].icon}</span>${esc(r.titulo||'(sem título)')}</button>`}
function openCalendarCreate(date,time='09:00'){if(pref('safeMode',false))return toast('Modo Seguro ativo: edição bloqueada.','warn');const day=date||isoDate(state.calendarDate||new Date());state.module='calendario';state.prefill={titulo:'',dataInicio:day,inicioEm:`${day}T${time}`,fimEm:`${day}T10:00`,status:'NOVO'};openModal(null,state.prefill)}
function bindCalendar(items){$('#calPrev').onclick=()=>{const d=new Date(state.calendarDate);if(state.calendarMode==='month')d.setMonth(d.getMonth()-1);else if(state.calendarMode==='week')d.setDate(d.getDate()-7);else d.setDate(d.getDate()-1);state.calendarDate=d;renderCalendar()};$('#calNext').onclick=()=>{const d=new Date(state.calendarDate);if(state.calendarMode==='month')d.setMonth(d.getMonth()+1);else if(state.calendarMode==='week')d.setDate(d.getDate()+7);else d.setDate(d.getDate()+1);state.calendarDate=d;renderCalendar()};$('#calToday').onclick=()=>{state.calendarDate=new Date();renderCalendar()};$('#calNew').onclick=()=>openCalendarCreate(isoDate(state.calendarDate||new Date()));$$('[data-cal]').forEach(b=>b.onclick=()=>{state.calendarMode=b.dataset.cal;renderCalendar()});$$('.daynum').forEach(b=>b.onclick=e=>{e.stopPropagation();openCalendarCreate(b.dataset.date)});$$('.cal-item').forEach(c=>c.onclick=e=>{e.stopPropagation();const row=items.find(x=>String(x.id)===String(c.dataset.id)&&x._m===c.dataset.module);if(row){state.module=row._m;openModal(row)}});$$('.cal-drop').forEach(z=>z.onclick=e=>{if(e.target.closest('.cal-item,.daynum,button,a,input,select,textarea'))return;openCalendarCreate(z.dataset.date)});let drag=null;$$('.cal-item').forEach(c=>{c.ondragstart=()=>drag={id:c.dataset.id,module:c.dataset.module}});$$('.cal-drop').forEach(z=>{z.ondragover=e=>{e.preventDefault();z.classList.add('over')};z.ondragleave=()=>z.classList.remove('over');z.ondrop=async e=>{e.preventDefault();e.stopPropagation();z.classList.remove('over');if(!drag)return;const row=items.find(x=>x.id===drag.id&&x._m===drag.module);const rd=rowDate(row||{},drag.module),old=String(rd.value||''),date=z.dataset.date;let value=date;if(old.includes('T'))value=`${date}T${old.split('T')[1]}`;await api(`/data?module=${drag.module}&id=${encodeURIComponent(drag.id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({[rd.key]:value})});invalidate(drag.module);toast('Item reagendado');renderCalendar()}})}
function sumRows(rows,key){return rows.reduce((a,r)=>a+num(r[key]),0)}
function latestRow(rows){return [...rows].sort((a,b)=>String(a.periodo||a.dataInicio||a.atualizadoEm||'').localeCompare(String(b.periodo||b.dataInicio||b.atualizadoEm||''))).at(-1)||{}}
function previousRow(rows){const x=[...rows].sort((a,b)=>String(a.periodo||a.dataInicio||a.atualizadoEm||'').localeCompare(String(b.periodo||b.dataInicio||b.atualizadoEm||'')));return x.length>1?x.at(-2):{}}
function compactDataToolbar(module,placeholder){return `<div class="toolbar module-toolbar distinctive-toolbar"><div class="filters"><input class="control table-search" id="moduleSearch" value="${attr(state.query)}" placeholder="${attr(placeholder)}"></div><div class="toolbar-actions"><button class="softbtn" id="exportBtn">Exportar CSV</button><button class="btn" id="distinctNew">${esc(newLabel(module))}</button></div></div>`}
function bindDistinctiveHistory(module,rerender){const sr=$('#moduleSearch');if(sr)sr.oninput=debounce(e=>{state.query=e.target.value;state.pageNum=1;rerender()},180);$('#exportBtn')&&($('#exportBtn').onclick=()=>exportCSV(module,filteredRows()));$('#distinctNew')&&($('#distinctNew').onclick=()=>{state.module=module;openModal()});$$('.edit-row').forEach(b=>b.onclick=()=>openModal(state.rows.find(r=>r.id===b.dataset.id)));$$('.dup-row').forEach(b=>b.onclick=()=>duplicateRow(b.dataset.id));$$('.delete-row').forEach(b=>b.onclick=()=>removeRow(b.dataset.id));$$('.rowcheck').forEach(c=>c.onchange=()=>{c.checked?state.selected.add(c.dataset.id):state.selected.delete(c.dataset.id);rerender()});$$('.sortbtn').forEach(b=>b.onclick=()=>{if(state.sortKey===b.dataset.sort)state.sortDir=state.sortDir==='asc'?'desc':'asc';else{state.sortKey=b.dataset.sort;state.sortDir='asc'}rerender()});$('#prevPage')&&($('#prevPage').onclick=()=>{state.pageNum--;rerender()});$('#nextPage')&&($('#nextPage').onclick=()=>{state.pageNum++;rerender()});$('#pageSize')&&($('#pageSize').onchange=e=>{state.pageSize=Number(e.target.value);setPref('pageSize',state.pageSize);state.pageNum=1;rerender()})}
function kpiDelta(cur,prev,invert=false){if(!prev||!isFinite(cur)||!isFinite(prev))return '<em class="kd flat">sem período anterior</em>';const d=(cur-prev)/Math.abs(prev)*100;if(Math.abs(d)<0.05)return '<em class="kd flat">= estável</em>';const good=invert?d<0:d>0;return `<em class="kd ${good?'up':'down'}">${d>0?'▲':'▼'} ${Math.abs(d).toLocaleString('pt-BR',{maximumFractionDigits:1})}% vs período anterior</em>`}
function periodSorted(rows){return [...rows].sort((a,b)=>String(a.periodo||a.dataInicio||a.criadoEm||'').localeCompare(String(b.periodo||b.dataInicio||b.criadoEm||'')))}
function trafficDerived(r){const inv=num(r.investimento),imp=num(r.impressoes),cli=num(r.cliques),cv=num(r.conversas),ld=num(r.leads),al=num(r.alcance);return {...r,ctr:num(r.ctr)||(imp?cli/imp*100:0),cpc:num(r.cpc)||(cli?inv/cli:0),cpm:num(r.cpm)||(imp?inv/imp*1000:0),frequencia:num(r.frequencia)||(al?imp/al:0),custoConversa:num(r.custoConversa)||(cv?inv/cv:0),custoLead:num(r.custoLead)||(ld?inv/ld:0)}}
function igEngagement(r){const reach=num(r.alcance);return reach?num(r.interacoes)/reach*100:0}
async function renderInstagramWorkspace(force=false){state.module='instagram';const d=await getRows('instagram',force);state.headers=d.headers||[];state.rows=d.rows||[];const rows=filteredRows(),sorted=periodSorted(state.rows),last=sorted.at(-1)||{},prev=sorted.length>1?sorted.at(-2):null,followers=num(last.seguidores),growth=num(last.crescimento)||(followers&&prev&&num(prev.seguidores)?((followers-num(prev.seguidores))/Math.max(1,num(prev.seguidores))*100):0);const L=k=>num(last[k]),P=k=>prev?num(prev[k]):0,eng=igEngagement(last),engPrev=prev?igEngagement(prev):0;const formats=[['Posts',sumRows(state.rows,'posts')],['Reels',sumRows(state.rows,'reels')],['Stories',sumRows(state.rows,'stories')]],totalFmt=formats.reduce((a,x)=>a+x[1],0),maxFmt=Math.max(1,...formats.map(x=>x[1]));const inter=[['Curtidas','curtidas'],['Comentários','comentarios'],['Compartilhamentos','compartilhamentos'],['Salvamentos','salvamentos']].map(([l,k])=>[l,sumRows(state.rows,k)]),maxInter=Math.max(1,...inter.map(x=>x[1]));const best=sorted.filter(r=>r.melhoresConteudos).slice(-5).reverse();const trend=sorted.slice(-8),maxFol=Math.max(1,...trend.map(r=>num(r.seguidores)));const kpi=(label,val,sub)=>`<article><small>${label}</small><strong>${val}</strong>${sub}</article>`,fmt=v=>v.toLocaleString('pt-BR');const empty=!state.rows.length;
$('#content').innerHTML=`<section class="social-cockpit"><header class="social-hero"><div><small>INSTAGRAM · SOCIAL MEDIA</small><h1>Desempenho e conteúdo</h1><p>Crescimento, alcance, interação e formatos em uma visão própria de social media. Dados lançados manualmente; preparado para a API da Meta/Instagram.</p></div><div class="social-orb">◎</div></header>${empty?`<div class="social-card empty-rich"><strong>Nenhum período lançado ainda</strong><p>Cadastre um registro por período (mês ou semana) com seguidores, alcance, impressões, visitas ao perfil e interações para ver o painel completo.</p><button class="btn" id="igFirst">${esc(newLabel('instagram'))}</button></div>`:''}<div class="social-kpis six"><article><small>Seguidores</small><strong>${fmt(followers)}</strong><span>${growth>=0?'+':''}${growth.toLocaleString('pt-BR',{maximumFractionDigits:1})}% crescimento · +${fmt(L('novosSeguidores'))} novos</span></article>${kpi('Alcance',fmt(L('alcance')),kpiDelta(L('alcance'),P('alcance')))}${kpi('Impressões',fmt(L('impressoes')),kpiDelta(L('impressoes'),P('impressoes')))}${kpi('Visitas ao perfil',fmt(L('visitasPerfil')),kpiDelta(L('visitasPerfil'),P('visitasPerfil')))}${kpi('Interações',fmt(L('interacoes')),kpiDelta(L('interacoes'),P('interacoes')))}${kpi('Engajamento',pct(eng),kpiDelta(eng,engPrev))}</div><p class="kpi-note">KPIs referem-se ao período mais recente (${esc(last.titulo||last.periodo||'—')}). Engajamento = interações ÷ alcance.</p><div class="social-grid"><section class="social-card"><div class="card-title"><div><small>MIX DE FORMATOS</small><h3>Produção registrada</h3></div></div>${formats.map(([l,v])=>`<div class="social-format"><span>${l}</span><div><i style="width:${v?Math.max(4,v/maxFmt*100):0}%"></i></div><b>${v}${totalFmt?` · ${Math.round(v/totalFmt*100)}%`:''}</b></div>`).join('')}</section><section class="social-card"><div class="card-title"><div><small>INTERAÇÕES</small><h3>Como o público reage</h3></div></div>${inter.map(([l,v])=>`<div class="social-format"><span>${l}</span><div><i style="width:${v?Math.max(4,v/maxInter*100):0}%"></i></div><b>${fmt(v)}</b></div>`).join('')}</section></div><div class="social-grid"><section class="social-card"><div class="card-title"><div><small>EVOLUÇÃO</small><h3>Seguidores por período</h3></div></div>${trend.map(r=>`<div class="social-format"><span>${esc(r.titulo||r.periodo||'Período')}</span><div><i style="width:${Math.max(4,num(r.seguidores)/maxFol*100)}%"></i></div><b>${fmt(num(r.seguidores))}</b></div>`).join('')||'<div class="empty compact">Sem períodos para exibir.</div>'}</section><section class="social-card social-best"><div class="card-title"><div><small>DESTAQUES</small><h3>Melhores conteúdos</h3></div></div>${best.map(r=>`<div class="social-highlight"><span>★</span><div><b>${esc(r.titulo||'Período')}</b><small>${esc(r.melhoresConteudos)}</small></div></div>`).join('')||'<div class="empty compact">Preencha “Melhores conteúdos” nos registros para formar esta lista.</div>'}</section></div><div class="distinct-history"><div class="module-section-head"><div><small>HISTÓRICO SOCIAL</small><h3>${rows.length} registro(s)</h3></div></div>${compactDataToolbar('instagram','Buscar período, perfil ou observação…')}${renderTable('instagram',rows)}</div></section>`;$('#igFirst')&&($('#igFirst').onclick=()=>{state.module='instagram';openModal()});bindDistinctiveHistory('instagram',()=>renderInstagramWorkspace())}
async function renderTrafficWorkspace(force=false){state.module='trafego';const d=await getRows('trafego',force);state.headers=d.headers||[];state.rows=d.rows||[];const rows=filteredRows().map(trafficDerived),T=trafficDerived({investimento:sumRows(state.rows,'investimento'),impressoes:sumRows(state.rows,'impressoes'),alcance:sumRows(state.rows,'alcance'),cliques:sumRows(state.rows,'cliques'),conversas:sumRows(state.rows,'conversas'),leads:sumRows(state.rows,'leads')}),sorted=periodSorted(state.rows).map(trafficDerived),cur=sorted.at(-1)||{},prv=sorted.length>1?sorted.at(-2):null,periods=sorted.slice(-8),maxSpend=Math.max(1,...periods.map(r=>num(r.investimento))),fmt=v=>num(v).toLocaleString('pt-BR'),empty=!state.rows.length;const kpi=(l,v,sub)=>`<article><small>${l}</small><strong>${v}</strong>${sub}</article>`,c=(k,inv)=>kpiDelta(num(cur[k]),prv?num(prv[k]):0,inv);const stage=(l,v,base)=>`<div style="--w:${base?Math.max(14,Math.min(100,v/base*100)):14}%"><span>${l}</span><b>${fmt(v)}</b></div>`;const rate=(a,b)=>b?pct(a/b*100):'—';
$('#content').innerHTML=`<section class="traffic-cockpit"><header class="traffic-hero"><div><small>TRÁFEGO PAGO · META ADS</small><h1>Mídia paga e conversão</h1><p>Investimento, eficiência, conversas e leads com leitura de funil, comparação entre períodos e histórico. Lançamento manual; preparado para Meta Ads.</p></div><div class="traffic-budget"><small>INVESTIMENTO TOTAL</small><strong>${money(T.investimento)}</strong></div></header>${empty?`<div class="traffic-card empty-rich"><strong>Nenhum período de mídia lançado</strong><p>Cadastre um registro por período/campanha com investimento, impressões, cliques, conversas e leads. CTR, CPC, CPM e custos são calculados automaticamente quando não informados.</p><button class="btn" id="trFirst">${esc(newLabel('trafego'))}</button></div>`:''}<div class="traffic-group"><h4>Entrega</h4><div class="traffic-kpis four">${kpi('Investimento',money(cur.investimento),c('investimento'))}${kpi('Impressões',fmt(cur.impressoes),c('impressoes'))}${kpi('Alcance',fmt(cur.alcance),c('alcance'))}${kpi('Frequência',num(cur.frequencia).toLocaleString('pt-BR',{maximumFractionDigits:2}),'<span>impressões ÷ alcance</span>')}</div></div><div class="traffic-group"><h4>Clique e custo</h4><div class="traffic-kpis four">${kpi('Cliques',fmt(cur.cliques),c('cliques'))}${kpi('CTR',pct(cur.ctr),c('ctr'))}${kpi('CPC',money(cur.cpc),c('cpc',true))}${kpi('CPM',money(cur.cpm),c('cpm',true))}</div></div><div class="traffic-group"><h4>Resultado</h4><div class="traffic-kpis four">${kpi('Conversas',fmt(cur.conversas),c('conversas'))}${kpi('Custo/conversa',money(cur.custoConversa),c('custoConversa',true))}${kpi('Leads',fmt(cur.leads),c('leads'))}${kpi('Custo/lead (CPL)',money(cur.custoLead),c('custoLead',true))}</div></div><p class="kpi-note">KPIs do período mais recente (${esc(cur.titulo||cur.periodo||'—')}). Funil e investimento abaixo consideram todos os períodos.</p><div class="traffic-grid"><section class="traffic-card"><div class="card-title"><div><small>FUNIL</small><h3>Da impressão ao lead</h3></div></div><div class="traffic-funnel">${stage('Impressões',T.impressoes,T.impressoes)}${stage('Cliques',T.cliques,T.impressoes)}${stage('Conversas',T.conversas,T.impressoes)}${stage('Leads',T.leads,T.impressoes)}</div><div class="funnel-rates"><span>Impressão→Clique <b>${rate(T.cliques,T.impressoes)}</b></span><span>Clique→Conversa <b>${rate(T.conversas,T.cliques)}</b></span><span>Conversa→Lead <b>${rate(T.leads,T.conversas)}</b></span></div></section><section class="traffic-card"><div class="card-title"><div><small>INVESTIMENTO</small><h3>Últimos períodos</h3></div></div>${periods.map(r=>`<div class="spend-row"><span>${esc(r.titulo||r.periodo||'Período')}</span><div><i style="width:${Math.max(4,num(r.investimento)/maxSpend*100)}%"></i></div><b>${money(r.investimento)}</b></div>`).join('')||'<div class="empty compact">Cadastre períodos para visualizar a evolução do investimento.</div>'}</section></div><section class="traffic-card"><div class="card-title"><div><small>COMPARAÇÃO</small><h3>Período atual × anterior</h3></div></div>${prv?`<div class="tablewrap"><table class="datatable compare-table"><thead><tr><th>Métrica</th><th>${esc(prv.titulo||prv.periodo||'Anterior')}</th><th>${esc(cur.titulo||cur.periodo||'Atual')}</th><th>Variação</th></tr></thead><tbody>${[['Investimento','investimento',money,true],['Impressões','impressoes',fmt,false],['Cliques','cliques',fmt,false],['CTR','ctr',pct,false],['CPC','cpc',money,true],['CPM','cpm',money,true],['Conversas','conversas',fmt,false],['Custo/conversa','custoConversa',money,true],['Leads','leads',fmt,false],['CPL','custoLead',money,true]].map(([l,k,f,inv])=>`<tr><td>${l}</td><td>${f(prv[k])}</td><td><b>${f(cur[k])}</b></td><td>${kpiDelta(num(cur[k]),num(prv[k]),inv&&k!=='investimento')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty compact">São necessários ao menos dois períodos para comparar.</div>'}</section><section class="traffic-card meta-prep"><div class="card-title"><div><small>INTEGRAÇÃO</small><h3>Preparação para Meta Ads</h3></div></div><p>Conexão automática <b>ainda não ativa</b>. O sistema funciona 100% offline com lançamento manual; os campos acima seguem os nomes das métricas do Gerenciador de Anúncios para facilitar importação futura.</p></section><div class="distinct-history"><div class="module-section-head"><div><small>HISTÓRICO DE MÍDIA</small><h3>${rows.length} registro(s)</h3></div></div>${compactDataToolbar('trafego','Buscar período ou campanha…')}${renderTable('trafego',rows)}</div></section>`;$('#trFirst')&&($('#trFirst').onclick=()=>{state.module='trafego';openModal()});bindDistinctiveHistory('trafego',()=>renderTrafficWorkspace())}

async function renderReports(){const d=await allData(['trafego','instagram','conteudos','projetos','tarefas','eventos','campanhas','equipe','solicitacoes']);const types=['Resumo executivo','Fechamento mensal','Planejamento editorial','Planejamento estratégico','Governança operacional','Tráfego semanal','Tráfego mensal','Instagram mensal','Conteúdos publicados','Projetos','Tarefas','Eventos','Campanhas'];const invest=d.trafego.reduce((a,r)=>a+num(r.investimento),0),conv=d.trafego.reduce((a,r)=>a+num(r.conversas),0),leads=d.trafego.reduce((a,r)=>a+num(r.leads),0);$('#content').innerHTML=`<div class="dashboard-head"><div><small>GESTÃO</small><h1>Relatórios</h1><p>Escolha um modelo, revise os dados e imprima em PDF quando precisar.</p></div><div><button class="softbtn" id="printReport">Imprimir / PDF</button></div></div><div class="report-grid">${types.map(t=>`<button class="report-card ${state.reportType===t?'active':''}" data-report="${attr(t)}"><span>▥</span><b>${esc(t)}</b><small>Gerar com dados locais</small></button>`).join('')}</div><div id="reportCanvas" class="report-canvas"><div class="report-header"><div class="report-logo">E</div><div><small>COLÉGIO EVOLUÇÃO · MARKETING</small><h2>${esc(state.reportType)}</h2><p>Gerado em ${new Intl.DateTimeFormat('pt-BR',{dateStyle:'long'}).format(new Date())}</p></div></div>${renderReportBody(state.reportType,d,{invest,conv,leads})}</div>`;$$('[data-report]').forEach(b=>b.onclick=()=>{state.reportType=b.dataset.report;renderReports()});$('#printReport').onclick=()=>window.print()}
function renderReportBody(type,d,k){if(/Fechamento mensal/i.test(type)){const month=new Date().toISOString().slice(0,7),s=closingSnapshot(d,month);return `<div class="report-kpis"><div><small>Conteúdos publicados</small><strong>${s.published}</strong></div><div><small>Projetos concluídos</small><strong>${s.doneProjects}</strong></div><div><small>Pendências</small><strong>${s.open.length}</strong></div><div><small>Atrasos</small><strong>${s.late}</strong></div></div><div class="report-summary"><h3>Fechamento mensal</h3><p>Consolidação executiva do período ${esc(month)} com produção, pendências e carry-over.</p></div>`}if(/Planejamento editorial/i.test(type)){const s=editorialSnapshot(d);return `<div class="report-kpis"><div><small>Conteúdos no mês</small><strong>${s.monthContents.length}</strong></div><div><small>Próximos 30 dias</small><strong>${s.scheduled.length}</strong></div><div><small>Campanhas sem cobertura</small><strong>${s.campaignRows.filter(x=>x._coverage==='CRÍTICO').length}</strong></div><div><small>Sem vínculo</small><strong>${s.unlinked.length}</strong></div></div><div class="report-summary"><h3>Planejamento editorial</h3><p>Mix de formatos, cobertura por segmento, perfis e campanhas.</p></div>`}if(/Planejamento estratégico/i.test(type)){const snap=strategicSnapshot(d),sp=strategyPrefs();return `<div class="report-kpis"><div><small>Qualidade</small><strong>${snap.qualityScore}%</strong></div><div><small>Conteúdos / meta</small><strong>${snap.monthPublished}/${sp.goals.contents}</strong></div><div><small>Projetos concluídos</small><strong>${snap.monthProjects}/${sp.goals.projects}</strong></div><div><small>Pontualidade</small><strong>${snap.onTime}%</strong></div></div><div class="report-summary"><h3>Planejamento estratégico</h3><p>${esc(sp.focus||'Sem foco estratégico definido para o período.')}</p><p>${snap.qualityIssues.length} pendência(s) de qualidade · ${snap.criticalRisks} item(ns) em risco crítico.</p></div>`}if(/Governança/i.test(type)){const snap=operationalSnapshot(d);const critical=snap.items.filter(r=>r._risk>=70).length,high=snap.items.filter(r=>r._risk>=50&&r._risk<70).length,overdue=snap.items.filter(r=>daysUntil(recordDate(r))<0).length;return `<div class="report-kpis"><div><small>Risco crítico</small><strong>${critical}</strong></div><div><small>Risco alto</small><strong>${high}</strong></div><div><small>Atrasados</small><strong>${overdue}</strong></div><div><small>Itens ativos</small><strong>${snap.items.length}</strong></div></div><div class="report-summary"><h3>Governança operacional</h3><p>Leitura local de prioridades, prazos, bloqueios e risco operacional.</p></div>`}if(/Tráfego/i.test(type))return `<div class="report-kpis"><div><small>Investimento</small><strong>${money(k.invest)}</strong></div><div><small>Conversas</small><strong>${k.conv}</strong></div><div><small>Leads</small><strong>${k.leads}</strong></div><div><small>Custo/lead</small><strong>${money(k.invest/Math.max(1,k.leads))}</strong></div></div>${reportTable(d.trafego,COLUMNS.trafego)}`;if(/Instagram/i.test(type))return `<div class="report-kpis"><div><small>Seguidores</small><strong>${d.instagram.length?num(d.instagram.at(-1).seguidores):0}</strong></div><div><small>Alcance</small><strong>${d.instagram.reduce((a,r)=>a+num(r.alcance),0)}</strong></div><div><small>Interações</small><strong>${d.instagram.reduce((a,r)=>a+num(r.interacoes),0)}</strong></div><div><small>Salvamentos</small><strong>${d.instagram.reduce((a,r)=>a+num(r.salvamentos),0)}</strong></div></div>${reportTable(d.instagram,COLUMNS.instagram)}`;const map={Projetos:'projetos',Tarefas:'tarefas',Eventos:'eventos',Campanhas:'campanhas','Conteúdos publicados':'conteudos'};if(map[type])return reportTable(d[map[type]],COLUMNS[map[type]]);return `<div class="report-kpis"><div><small>Tarefas</small><strong>${d.tarefas.length}</strong></div><div><small>Conteúdos</small><strong>${d.conteudos.length}</strong></div><div><small>Projetos</small><strong>${d.projetos.length}</strong></div><div><small>Campanhas</small><strong>${d.campanhas.length}</strong></div></div><div class="report-summary"><h3>Resumo operacional</h3><p>O EVO MKT consolida os registros locais em XLSX para facilitar acompanhamento, planejamento e prestação de contas do marketing.</p></div>`}
function reportTable(rows,cols){return `<table class="report-table"><thead><tr>${cols.slice(0,6).map(c=>`<th>${esc(c[1])}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,50).map(r=>`<tr>${cols.slice(0,6).map(([k,,t])=>`<td>${valueCell(r,k,t).replace(/<[^>]+>/g,'')}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="6">Sem dados.</td></tr>'}</tbody></table>`}

async function renderFiles(){state.module='arquivos';const data=await allData(['arquivos','conteudos','projetos','eventos','solicitacoes']);state.rows=data.arquivos||[];const rows=state.rows;const deliveries=[];PRODUCTION_MODULES.forEach(m=>(data[m]||[]).forEach(r=>{if(r.arquivoFinal)deliveries.push({...r,_module:m,_ref:r.arquivoFinal,_state:r.arquivoAprovacaoStatus||'FINAL',_version:r.arquivoVersaoAtual||'',_date:r.arquivoFinalEm||r.arquivoAtualizadoEm||r.atualizadoEm})}));deliveries.sort((a,b)=>String(b._date||'').localeCompare(String(a._date||'')));const approved=deliveries.filter(r=>r._state==='APROVADO').length,pending=deliveries.filter(r=>r._state==='AGUARDANDO').length;$('#content').innerHTML=`${hero('arquivos',rows)}<div class="kpis"><div class="kpi"><small>Biblioteca</small><strong>${rows.length}</strong></div><div class="kpi orange"><small>Entregas finais</small><strong>${deliveries.length}</strong></div><div class="kpi green"><small>Finais aprovados</small><strong>${approved}</strong></div><div class="kpi red"><small>Aguardando aprovação</small><strong>${pending}</strong></div></div><div class="file-toolbar"><div class="library-tabs"><button class="softbtn active" data-file-view="library">Biblioteca geral</button><button class="softbtn" data-file-view="deliveries">Entregas</button></div><button class="btn" id="fileNew">${newLabel('arquivos')}</button></div><div id="fileViewLibrary">${rows.length?`<div class="file-grid">${rows.map(r=>`<article class="file-card"><div class="file-icon">${/video/i.test(r.tipoArquivo||'')?'▶':/image|foto/i.test(r.tipoArquivo||'')?'▧':'▤'}</div><div><b>${esc(r.titulo||'Arquivo')}</b><small>${esc(r.tipoArquivo||'Sem tipo')}</small><p title="${attr(r.caminhoArquivo)}">${esc(r.caminhoArquivo||'Caminho não informado')}</p>${r.origemModulo?`<small>${esc(MODULES[r.origemModulo]?.label||r.origemModulo)} · ${esc(r.versaoOrigem?`v${r.versaoOrigem}`:'')}</small>`:''}</div><span class="file-status ${/SIM/i.test(r.existe||'')?'ok':'missing'}">${/SIM/i.test(r.existe||'')?'Disponível':'Verificar caminho'}</span><div class="actions"><button class="edit-file" data-id="${attr(r.id)}">Editar</button><button class="delete-file" data-id="${attr(r.id)}">Excluir</button></div></article>`).join('')}</div>`:emptyState('arquivos')}</div><div id="fileViewDeliveries" hidden>${deliveries.length?`<div class="delivery-library">${deliveries.map(r=>`<article class="delivery-card"><div class="delivery-card-top"><span class="status-badge ${r._state==='APROVADO'?'good':r._state==='AGUARDANDO'?'warn':'neutral'}">${esc(r._state)}</span><small>${esc(MODULES[r._module]?.label||r._module)} · ${r._version?`v${esc(r._version)}`:'versão —'}</small></div><h3>${esc(r.titulo||'Entrega')}</h3><p>${productionRefLink(r._ref)}</p><footer><span>${esc(r.arquivoFinalPor||r.responsavel||'Equipe')}</span><time>${fmtDateTime(r._date)}</time><button class="softbtn open-production-delivery" data-module="${attr(r._module)}" data-id="${attr(r.id)}">Ver versões</button></footer></article>`).join('')}</div>`:'<div class="empty"><strong>Nenhuma entrega final registrada</strong><span>Marque uma versão como FINAL dentro de Conteúdo, Projeto, Evento ou Solicitação.</span></div>'}</div>`;$('#fileNew').onclick=()=>openModal();$$('.edit-file').forEach(b=>b.onclick=()=>openModal(rows.find(r=>r.id===b.dataset.id)));$$('.delete-file').forEach(b=>b.onclick=()=>removeRow(b.dataset.id));$$('[data-file-view]').forEach(b=>b.onclick=()=>{$$('[data-file-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');const del=b.dataset.fileView==='deliveries';document.getElementById('fileViewLibrary').hidden=del;document.getElementById('fileViewDeliveries').hidden=!del});$$('.open-production-delivery').forEach(b=>b.onclick=()=>openProduction(b.dataset.module,b.dataset.id))}
async function renderIntegrations(){state.module='integracoes';const d=await getRows('integracoes');state.rows=d.rows||[];const providers=['Meta Ads','Instagram','Google Calendar','Google Drive','MCP'];const rows=state.rows;$('#content').innerHTML=`${hero('integracoes',rows)}<div class="connector-grid final">${providers.map(p=>{const r=rows.find(x=>String(x.provedor||x.titulo||'').toLowerCase().includes(p.toLowerCase()));const s=r?.conexaoStatus||'DESCONECTADO';return `<div class="connector-card"><div class="connector-icon">⛓</div><div><b>${p}</b><small>${esc(s)}</small></div><span class="dot ${/CONECTADO/.test(s)&&!/DESC/.test(s)?'on':''}"></span><p>${r?.ultimaSincronizacao?`Última sincronização: ${fmtDateTime(r.ultimaSincronizacao)}`:'Integração opcional. O app continua local mesmo desconectado.'}</p></div>`}).join('')}</div><div class="card"><div class="card-title"><div><small>CONFIGURAÇÕES</small><h3>Registros de integração</h3></div><button class="btn" id="integrationNew">+ Nova integração</button></div>${renderTable('integracoes',rows)}</div>`;$('#integrationNew').onclick=()=>openModal();bindModuleEvents()}


