function addBusinessDays(base,days){const d=new Date(base||Date.now());let n=0;while(n<Math.max(0,Number(days)||0)){d.setDate(d.getDate()+1);const w=d.getDay();if(w!==0&&w!==6)n++}return isoDate(d)}
