async function renderCentralData(){const h=await api('/health');const totalSize=(h.modules||[]).reduce((a,m)=>a+(m.size||0),0);$('#content').innerHTML=`<div class="dashboard-head"><div><small>SISTEMA</small><h1>Central de Dados</h1><p>Visão consolidada das planilhas XLSX usadas pelo EVO MKT.</p></div><div><button class="softbtn" id="dataDiag">Exportar diagnóstico</button><button class="btn" id="dataBackup">Criar backup</button></div></div><div class="kpis"><div class="kpi green"><small>Planilhas</small><strong>${h.modules.length}</strong></div><div class="kpi"><small>Registros</small><strong>${h.records}</strong></div><div class="kpi orange"><small>Espaço utilizado</small><strong>${(totalSize/1024).toFixed(0)} KB</strong></div><div class="kpi ${h.modules.every(m=>m.ok)?'green':'red'}"><small>Integridade</small><strong>${h.modules.every(m=>m.ok)?'OK':'Atenção'}</strong></div></div><div class="card"><div class="card-title"><div><small>PLANILHAS</small><h3>Inventário local</h3></div><button class="softbtn" id="dataRefresh">Auditar novamente</button></div><div class="data-grid">${h.modules.map(m=>`<div class="data-row"><div class="sheet-icon">X</div><div><b>${esc(m.file)}</b><small>${esc(m.module)} · ${m.records||0} registro(s)</small></div><span>${((m.size||0)/1024).toFixed(1)} KB</span><time>${fmtDateTime(m.modified)}</time><strong class="${m.ok?'ok':'bad'}">${m.ok?'OK':'ERRO'}</strong></div>`).join('')}</div></div>`;$('#dataDiag').onclick=()=>downloadJSON(`EVO_MKT_DIAGNOSTICO_${today()}.json`,h);$('#dataBackup').onclick=backup;$('#dataRefresh').onclick=renderCentralData}
async function backup(){try{const x=await api('/backup',{method:'POST'});const stamp=new Date().toISOString();setPref('lastBackup',{stamp,file:x.file||''});toast('Backup criado com sucesso');return x}catch(e){toast('Erro no backup: '+e.message,'bad');throw e}}
async function renderBackup(){const last=pref('lastBackup',null);$('#content').innerHTML=`<div class="dashboard-head"><div><small>SISTEMA</small><h1>Backup</h1><p>Proteção local dos seus arquivos XLSX.</p></div><button class="btn" id="backupNow">Criar backup agora</button></div><div class="backup-hero"><div class="backup-shield">✓</div><div><small>ÚLTIMO BACKUP CRIADO PELO APP</small><h2>${last?fmtDateTime(last.stamp):'Ainda não registrado nesta instalação'}</h2><p>${last?.file?esc(last.file):'Crie um backup manual antes de alterações importantes ou importações.'}</p></div></div><div class="grid2"><div class="card"><h3>Quando criar backup?</h3><div class="check-list"><span>✓ Antes de grandes alterações</span><span>✓ Antes de importar dados</span><span>✓ Antes de atualizar a versão</span><span>✓ Periodicamente durante o uso</span></div></div><div class="card"><h3>Como funciona</h3><p>O runtime local mantém seus dados em XLSX e cria cópias de segurança na pasta <b>backups</b>, ao lado do aplicativo.</p><div class="info-note">As integrações externas nunca são necessárias para restaurar os dados locais.</div></div></div>`;$('#backupNow').onclick=async()=>{await backup();renderBackup()}}

async function renderSettings(){state.module='configuracoes';const d=await getRows('configuracoes');state.rows=d.rows||[];const compact=pref('compact',false),reduced=pref('reducedMotion',false),defaultPage=pref('defaultPage','hoje');$('#content').innerHTML=`<div class="dashboard-head"><div><small>SISTEMA</small><h1>Configurações</h1><p>Preferências locais e informações institucionais.</p></div><button class="btn" id="configNew">+ Nova configuração</button></div><div class="settings-grid"><div class="card"><div class="card-title"><div><small>APARÊNCIA</small><h3>Experiência no Windows</h3></div></div><label class="setting-row"><div><b>Modo compacto</b><small>Reduz espaços e exibe mais informação na tela.</small></div><input type="checkbox" id="compactToggle" ${compact?'checked':''}></label><label class="setting-row"><div><b>Reduzir animações</b><small>Minimiza transições visuais.</small></div><input type="checkbox" id="motionToggle" ${reduced?'checked':''}></label><label class="setting-row"><div><b>Alto contraste</b><small>Reforça contraste, bordas e foco do teclado.</small></div><input type="checkbox" id="contrastToggle" ${pref('highContrast',false)?'checked':''}></label><label class="setting-row"><div><b>Escala do texto</b><small>Ajuste local de leitura da interface.</small></div><select id="fontScale" class="control">${[['0.95','95%'],['1','100%'],['1.08','108%'],['1.15','115%']].map(([v,l])=>`<option value="${v}" ${String(pref('fontScale','1'))===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="setting-row"><div><b>Bloquear por inatividade</b><small>Encerra a sessão da interface após o período escolhido.</small></div><select id="autoLock" class="control">${[['0','Desativado'],['15','15 min'],['30','30 min'],['60','60 min']].map(([v,l])=>`<option value="${v}" ${String(pref('autoLockMinutes','0'))===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="setting-row"><div><b>Página inicial</b><small>Escolha o primeiro painel ao abrir.</small></div><select id="defaultPage" class="control">${['hoje','minhaarea','dashboard','central','governanca','estrategia','editorial','fechamento','calendario','manutencao'].map(p=>`<option value="${p}" ${defaultPage===p?'selected':''}>${MODULES[p].label}</option>`).join('')}</select></label></div><div class="card"><div class="card-title"><div><small>IDENTIDADE</small><h3>Colégio Evolução</h3></div></div><div class="brand-preview"><div class="brandmark big">E</div><div><b>EVO MKT</b><span>Azul + laranja · roxo reservado ao Infantil</span></div></div><div class="palette"><i style="background:#1E3A8A"></i><i style="background:#F5820B"></i><i style="background:#14265C"></i><i style="background:#793A8C"></i></div></div></div><div class="card"><div class="card-title"><div><small>INSTITUCIONAL</small><h3>Missão, visão, valores e outras configurações</h3></div></div>${renderTable('configuracoes',state.rows)}</div>`;$('#configNew').onclick=()=>openModal();$('#compactToggle').onchange=e=>{setPref('compact',e.target.checked);document.body.classList.toggle('compact',e.target.checked)};$('#motionToggle').onchange=e=>{setPref('reducedMotion',e.target.checked);document.body.classList.toggle('reduced-motion',e.target.checked)};$('#contrastToggle').onchange=e=>{setPref('highContrast',e.target.checked);document.body.classList.toggle('high-contrast',e.target.checked)};$('#fontScale').onchange=e=>{setPref('fontScale',e.target.value);document.documentElement.style.setProperty('--evo-font-scale',e.target.value)};$('#autoLock').onchange=e=>setPref('autoLockMinutes',e.target.value);$('#defaultPage').onchange=e=>setPref('defaultPage',e.target.value);bindModuleEvents()}
async function renderHealth(){const h=await api('/health');let heartbeat='OK';try{await api('/heartbeat')}catch{heartbeat='ERRO'}const allOk=h.modules.every(m=>m.ok)&&heartbeat==='OK';$('#content').innerHTML=`<div class="dashboard-head"><div><small>SISTEMA</small><h1>Saúde do Sistema</h1><p>Diagnóstico da instalação local do EVO MKT.</p></div><span class="health-pill ${allOk?'ok':'bad'}">${allOk?'Sistema normal':'Atenção necessária'}</span></div><div class="kpis"><div class="kpi green"><small>Interface</small><strong>${VERSION}</strong></div><div class="kpi"><small>Runtime</small><strong>${esc(h.version||'Go')}</strong></div><div class="kpi orange"><small>Registros</small><strong>${h.records}</strong></div><div class="kpi ${allOk?'green':'red'}"><small>Heartbeat</small><strong>${heartbeat}</strong></div></div><div class="grid2"><div class="card"><h3>Prontidão</h3><div class="check-list"><span>${h.modules.every(m=>m.ok)?'✓':'!'} Planilhas estruturadas</span><span>✓ Runtime local sem Node/npm</span><span>✓ Dados separados do código</span><span>✓ Servidor local protegido pelo ciclo de vida do app</span><span>✓ Backup manual disponível</span></div></div><div class="card"><h3>Ambiente</h3><p class="mono">${esc(h.dataDir)}</p><div class="info-note">O EVO MKT funciona sem Hostinger, PostgreSQL ou banco remoto.</div><button class="softbtn" id="healthDiag">Exportar diagnóstico</button></div></div><div class="card" style="margin-top:16px"><h3>Planilhas</h3>${h.modules.map(x=>`<div class="healthrow"><strong>${esc(x.file)}</strong><span>${x.records||0} registros</span><span>${((x.size||0)/1024).toFixed(1)} KB</span><span class="${x.ok?'ok':'bad'}">${x.ok?'OK':'ERRO'}</span></div>`).join('')}</div>`;$('#healthDiag').onclick=()=>downloadJSON(`EVO_MKT_SAUDE_${today()}.json`,h)}

async function globalSearch(q){
  q=q.trim();
  if(!q)return;
  if(q.startsWith('>'))return runCommand(q.slice(1).trim());
  const ops={}, plain=[];
  q.split(/\s+/).forEach(t=>{const i=t.indexOf(':');if(i>0)ops[t.slice(0,i).toLowerCase()]=t.slice(i+1);else plain.push(t)});
  let rows=[];
  if(Object.keys(ops).length){
    const d=await allData(DATA_MODULES.filter(canAccess));
    Object.entries(d).forEach(([m,rs])=>rs.forEach(r=>rows.push({...r,module:m})));
    const map={status:'status',responsavel:'responsavel',segmento:'segmento',prioridade:'prioridade',prazo:'prazo',tag:'tags',titulo:'titulo'};
    rows=rows.filter(r=>Object.entries(ops).every(([k,v])=>String(r[map[k]||k]||'').toLowerCase().includes(v.toLowerCase())) && (!plain.length||plain.every(p=>Object.values(r).some(v=>String(v||'').toLowerCase().includes(p.toLowerCase())))));
  }else{
    rows=await api('/search?q='+encodeURIComponent(q));
  }
  rows=rows.filter(r=>canAccess(r.module));
  setTitle('Busca global',`${rows.length} resultado(s) para “${q}”`);
  const body=rows.length
    ? `<div class="tablewrap"><table class="datatable"><thead><tr><th>Módulo</th><th>Título</th><th>Status</th><th>Responsável</th><th>Prazo</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="badge search-go" data-go="${attr(x.module)}">${esc(MODULES[x.module]?.label||x.module)}</button></td><td class="titlecell">${esc(x.titulo||'(sem título)')}</td><td>${valueCell(x,'status')}</td><td>${esc(x.responsavel||'—')}</td><td>${fmtDate(x.prazo||x.publicacaoEm||x.dataInicio)}</td></tr>`).join('')}</tbody></table></div>`
    : `<div class="module-empty blue"><div class="empty-illustration">⌕</div><div><h3>Nenhum resultado</h3><p>Tente outro termo ou use operadores de busca.</p></div></div>`;
  $('#content').innerHTML=`<div class="search-results-head"><div><small>BUSCA GLOBAL</small><h1>${rows.length} resultado(s)</h1></div><div class="search-help">Use filtros como <code>status:ATIVA</code> <code>responsavel:Nome</code> <code>segmento:Infantil</code></div></div>${body}`;
  bindGoButtons();
}
function runCommand(cmd){const c=cmd.toLowerCase().trim();const manager=internalSession?.role==='manager';if(c==='backup')return manager?go('backup'):toast('Ação disponível apenas para a Gerente','warn');if(c==='manutencao'||c==='manutenção')return manager?go('manutencao'):toast('Ação disponível apenas para a Gerente','warn');if(c==='saude'||c==='saúde')return manager?go('saude'):toast('Ação disponível apenas para a Gerente','warn');if(c==='central dados'||c==='dados')return manager?go('centraldados'):toast('Ação disponível apenas para a Gerente','warn');if(c==='modo seguro'){if(!manager)return toast('Ação disponível apenas para a Gerente','warn');setPref('safeMode',true);document.body.classList.add('safe-mode');updateHeader();return toast('Modo Seguro ativado','warn')}if(c==='sair modo seguro'||c==='desativar modo seguro'){if(!manager)return toast('Ação disponível apenas para a Gerente','warn');setPref('safeMode',false);document.body.classList.remove('safe-mode');updateHeader();return toast('Modo Seguro desativado')}if(c.includes('nova tarefa')){go('tarefas').then(()=>openModal())}else if(c.includes('novo conteúdo')||c.includes('novo conteudo')){go('conteudos').then(()=>openModal())}else if(c.includes('novo evento')){go('eventos').then(()=>openModal())}else if(c.includes('calend'))go('calendario');else toast('Comando não reconhecido','warn')}



function logClientIssue(type,message,stack=''){try{const key='evo.clientIssues';const list=JSON.parse(localStorage.getItem(key)||'[]');list.unshift({at:new Date().toISOString(),type,message:String(message||'').slice(0,500),stack:String(stack||'').slice(0,1200),page:state?.page||''});localStorage.setItem(key,JSON.stringify(list.slice(0,30)))}catch{}}
window.addEventListener('error',e=>logClientIssue('error',e.message,e.error?.stack||''));window.addEventListener('unhandledrejection',e=>logClientIssue('promise',e.reason?.message||e.reason||'Promise rejeitada',e.reason?.stack||''));
function clientIssues(){try{return JSON.parse(localStorage.getItem('evo.clientIssues')||'[]')}catch{return[]}}
function clearRuntimeCache(){state.cache.clear();state.cacheAt.clear();toast('Cache de leitura limpo')}
function draftKeys(){return Object.keys(localStorage).filter(k=>k.startsWith('evo.draft.'))}
function clearDrafts(){draftKeys().forEach(k=>localStorage.removeItem(k));toast('Rascunhos locais removidos')}
function exportPreferences(){const prefs={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k?.startsWith('evo.')&&!k.includes('clientIssues')&&!k.startsWith('evo.draft.'))prefs[k]=localStorage.getItem(k)}downloadJSON(`EVO_MKT_PREFERENCIAS_${today()}.json`,{version:VERSION,generatedAt:new Date().toISOString(),prefs})}
function importPreferencesFile(file){const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);if(!obj?.prefs||typeof obj.prefs!=='object')throw new Error('Arquivo inválido');Object.entries(obj.prefs).forEach(([k,v])=>{if(k.startsWith('evo.'))localStorage.setItem(k,String(v))});toast('Preferências importadas. Reabrindo interface…');setTimeout(()=>location.reload(),600)}catch(e){toast('Não foi possível importar: '+e.message,'bad')}};r.readAsText(file)}
async function exportFullLocalSnapshot(){const data=await allData(DATA_MODULES);downloadJSON(`EVO_MKT_SNAPSHOT_DADOS_${today()}.json`,{version:VERSION,generatedAt:new Date().toISOString(),warning:'Snapshot de consulta/exportação. Os XLSX continuam sendo a fonte oficial.',modules:data})}
function maintenancePrefs(){return {safeMode:pref('safeMode',false),highContrast:pref('highContrast',false),fontScale:pref('fontScale','1'),autoLockMinutes:pref('autoLockMinutes','0'),lastBackup:pref('lastBackup',null)}}
function backupAgeLabel(last){if(!last?.stamp)return 'Nunca registrado';const ms=Date.now()-new Date(last.stamp).getTime(),h=Math.max(0,Math.floor(ms/3600000));if(h<24)return `${h}h`;return `${Math.floor(h/24)} dia(s)`}
async function runSelfTest(){const result={version:VERSION,at:new Date().toISOString(),checks:[]};try{const h=await api('/health');result.health=h;result.checks.push({name:'Runtime /health',ok:true,detail:`${h.modules?.length||0} módulos`});result.checks.push({name:'Planilhas',ok:(h.modules||[]).every(x=>x.ok),detail:`${(h.modules||[]).filter(x=>x.ok).length}/${h.modules?.length||0} OK`})}catch(e){result.checks.push({name:'Runtime /health',ok:false,detail:e.message})}try{await api('/heartbeat');result.checks.push({name:'Heartbeat',ok:true,detail:'OK'})}catch(e){result.checks.push({name:'Heartbeat',ok:false,detail:e.message})}for(const m of ['tarefas','conteudos','projetos','solicitacoes']){try{const d=await getRows(m,true);result.checks.push({name:`Leitura ${m}`,ok:Array.isArray(d.rows),detail:`${d.rows?.length||0} registros`})}catch(e){result.checks.push({name:`Leitura ${m}`,ok:false,detail:e.message})}}return result}
function downloadSupportBundle(h,test){const prefs=maintenancePrefs();downloadJSON(`EVO_MKT_SUPORTE_${today()}.json`,{app:'EVO MKT',interfaceVersion:VERSION,generatedAt:new Date().toISOString(),health:h,selfTest:test||null,preferences:{safeMode:prefs.safeMode,highContrast:prefs.highContrast,fontScale:prefs.fontScale,autoLockMinutes:prefs.autoLockMinutes},note:'Pacote de diagnóstico sem códigos de acesso ou conteúdo das planilhas.'})}
async function renderMaintenance(){if(internalSession?.role!=='manager')return go('minhaarea');let h,heartbeat='OK';try{h=await api('/health')}catch(e){h={version:'—',records:0,modules:[],dataDir:'—',error:e.message}}try{await api('/heartbeat')}catch{heartbeat='ERRO'}const mp=maintenancePrefs(),mods=h.modules||[],ok=mods.length&&mods.every(x=>x.ok)&&heartbeat==='OK';const backupFresh=mp.lastBackup?.stamp&&(Date.now()-new Date(mp.lastBackup.stamp).getTime())<7*86400000;$('#content').innerHTML=`<div class="dashboard-head"><div><small>SISTEMA</small><h1>Central de Manutenção</h1><p>Atualização, diagnóstico, recuperação e segurança operacional da instalação local.</p></div><span class="health-pill ${ok?'ok':'bad'}">${ok?'Pronto para uso':'Verificar instalação'}</span></div><div class="kpis"><div class="kpi ${ok?'green':'red'}"><small>Integridade</small><strong>${ok?'OK':'ATENÇÃO'}</strong></div><div class="kpi"><small>Planilhas</small><strong>${mods.length}</strong></div><div class="kpi ${backupFresh?'green':'orange'}"><small>Último backup</small><strong>${backupAgeLabel(mp.lastBackup)}</strong></div><div class="kpi ${mp.safeMode?'orange':'green'}"><small>Modo Seguro</small><strong>${mp.safeMode?'ATIVO':'DESATIVADO'}</strong></div></div><div class="maintenance-grid"><section class="card"><div class="card-title"><div><small>PRÉ-ATUALIZAÇÃO</small><h3>Checklist seguro</h3></div></div><div class="check-list"><span>${ok?'✓':'!'} Runtime e heartbeat</span><span>${mods.every(x=>x.ok)?'✓':'!'} Integridade das planilhas</span><span>${backupFresh?'✓':'!'} Backup nos últimos 7 dias</span><span>✓ Dados separados do código</span><span>✓ Atualização deve substituir código, nunca a pasta DADOS</span></div><button class="btn" id="maintenanceBackup">Criar backup agora</button></section><section class="card"><div class="card-title"><div><small>DIAGNÓSTICO</small><h3>Teste do sistema</h3></div></div><p>Executa somente leituras de saúde e módulos críticos. Não altera registros.</p><button class="softbtn" id="maintenanceTest">Executar autoteste</button><div id="maintenanceTestResult" class="maintenance-test"></div></section><section class="card"><div class="card-title"><div><small>PROTEÇÃO</small><h3>Modo Seguro</h3></div></div><p>Bloqueia criação e edição pela interface enquanto você diagnostica ou prepara uma atualização.</p><label class="setting-row"><div><b>Modo Seguro</b><small>Somente interface; não altera o runtime.</small></div><input type="checkbox" id="safeModeToggle" ${mp.safeMode?'checked':''}></label></section><section class="card"><div class="card-title"><div><small>SUPORTE</small><h3>Pacote de diagnóstico</h3></div></div><p>Exporta versão, integridade, saúde e preferências técnicas sem incluir códigos de acesso nem conteúdo das planilhas.</p><button class="softbtn" id="supportBundle">Exportar diagnóstico</button><div class="maintenance-actions"><button class="softbtn" id="exportSnapshot">Snapshot JSON</button><button class="softbtn" id="exportPrefs">Exportar preferências</button><button class="softbtn" id="importPrefs">Importar preferências</button><input type="file" id="importPrefsFile" accept="application/json,.json" hidden></div></section><section class="card"><div class="card-title"><div><small>LIMPEZA SEGURA</small><h3>Interface local</h3></div></div><p>Essas ações não alteram os arquivos XLSX.</p><div class="maintenance-actions"><button class="softbtn" id="clearCache">Limpar cache</button><button class="softbtn" id="clearDrafts">Limpar rascunhos (${draftKeys().length})</button><button class="softbtn" id="clearIssues">Limpar log (${clientIssues().length})</button></div></section><section class="card span2"><div class="card-title"><div><small>RECUPERAÇÃO</small><h3>Ordem recomendada</h3></div></div><div class="recovery-steps"><b>1.</b><span>Feche o EVO MKT.</span><b>2.</b><span>Faça uma cópia da pasta DADOS atual antes de qualquer substituição.</span><b>3.</b><span>Use um backup anterior somente se a planilha atual estiver realmente inválida.</span><b>4.</b><span>Depois da recuperação, abra Saúde do Sistema e execute o autoteste.</span><b>5.</b><span>Nunca substitua a pasta DADOS ao atualizar apenas o código do app.</span></div></section><section class="card span2"><div class="card-title"><div><small>ATALHOS</small><h3>Navegação rápida</h3></div></div><div class="shortcut-grid"><span><kbd>Ctrl K</kbd> Busca global</span><span><kbd>Ctrl N</kbd> Novo registro</span><span><kbd>Alt H</kbd> Hoje</span><span><kbd>Alt M</kbd> Minha Área</span><span><kbd>Alt C</kbd> Calendário</span><span><kbd>Alt G</kbd> Governança</span><span><kbd>Alt S</kbd> Saúde</span><span><kbd>?</kbd> Ajuda de atalhos</span></div></section></div>`;$('#maintenanceBackup').onclick=async()=>{await backup();renderMaintenance()};$('#safeModeToggle').onchange=e=>{setPref('safeMode',e.target.checked);toast(e.target.checked?'Modo Seguro ativado':'Modo Seguro desativado',e.target.checked?'warn':'ok');updateHeader()};$('#maintenanceTest').onclick=async()=>{const el=$('#maintenanceTestResult');el.innerHTML='Executando…';const t=await runSelfTest();el.innerHTML=t.checks.map(x=>`<div class="selftest ${x.ok?'ok':'bad'}"><b>${x.ok?'✓':'!'}</b><span>${esc(x.name)}</span><small>${esc(x.detail)}</small></div>`).join('');setPref('lastSelfTest',{at:t.at,ok:t.checks.every(x=>x.ok)});window.__evoLastTest=t};$('#supportBundle').onclick=()=>downloadSupportBundle(h,window.__evoLastTest||null);$('#exportSnapshot').onclick=exportFullLocalSnapshot;$('#exportPrefs').onclick=exportPreferences;$('#importPrefs').onclick=()=>$('#importPrefsFile').click();$('#importPrefsFile').onchange=e=>{if(e.target.files?.[0])importPreferencesFile(e.target.files[0])};$('#clearCache').onclick=clearRuntimeCache;$('#clearDrafts').onclick=()=>{if(confirm('Remover todos os rascunhos locais não salvos?')){clearDrafts();renderMaintenance()}};$('#clearIssues').onclick=()=>{localStorage.removeItem('evo.clientIssues');toast('Log técnico limpo');renderMaintenance()}}
function showShortcutHelp(){let el=document.getElementById('shortcutHelp');if(el)el.remove();el=document.createElement('div');el.id='shortcutHelp';el.className='shortcut-help';el.innerHTML=`<div class="shortcut-help-card"><div class="modalhead"><div><h2>Atalhos do EVO MKT</h2><p>Navegação rápida no Windows</p></div><button class="iconbtn" id="shortcutHelpClose">×</button></div><div class="shortcut-grid"><span><kbd>Ctrl K</kbd> Busca global</span><span><kbd>Ctrl N</kbd> Novo registro</span><span><kbd>Alt H</kbd> Hoje</span><span><kbd>Alt M</kbd> Minha Área</span><span><kbd>Alt C</kbd> Calendário</span><span><kbd>Alt G</kbd> Governança</span><span><kbd>Alt S</kbd> Saúde</span><span><kbd>Esc</kbd> Fechar janela</span></div></div>`;document.body.appendChild(el);$('#shortcutHelpClose').onclick=()=>el.remove();el.onclick=e=>{if(e.target===el)el.remove()}}
let __evoLastActivity=Date.now();
function setupAutoLock(){['mousemove','keydown','mousedown','touchstart'].forEach(ev=>document.addEventListener(ev,()=>__evoLastActivity=Date.now(),{passive:true}));setInterval(()=>{const mins=Number(pref('autoLockMinutes','0'));if(!mins||!internalSession)return;if(Date.now()-__evoLastActivity>=mins*60000){sessionStorage.removeItem('evo.internal.session');location.reload()}},30000)}
function startApp(){renderInternalUser();renderNav();document.body.classList.toggle('compact',pref('compact',false));document.body.classList.toggle('reduced-motion',pref('reducedMotion',false));document.body.classList.toggle('high-contrast',pref('highContrast',false));document.documentElement.style.setProperty('--evo-font-scale',pref('fontScale','1'));document.body.classList.toggle('safe-mode',pref('safeMode',false));document.body.classList.toggle('sidebar-collapsed',pref('sidebarCollapsed',false));const urlPage=new URLSearchParams(location.search).get('page'),preferred=internalSession?.role==='manager'?(urlPage||pref('defaultPage','hoje')):'minhaarea',initial=canAccess(preferred)?preferred:(internalSession?.role==='manager'?'hoje':'minhaarea');go(initial);$('#newBtn').onclick=()=>{if(DATA_MODULES.includes(state.page)&&canAccess(state.page)){state.module=state.page;openModal()}};$('#backupBtn').onclick=()=>{if(internalSession?.role==='manager')go('backup')};$('#notifyBtn').onclick=()=>{if(internalSession?.role==='manager')go('central');else go('minhaarea')};$('#closeModal').onclick=closeModal;$('#cancelModal').onclick=closeModal;$('#recordForm').onsubmit=saveForm;$('#modal').onclick=e=>{if(e.target===$('#modal'))closeModal()};$('#globalSearch').onkeydown=e=>{if(e.key==='Enter')globalSearch(e.target.value)};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();$('#globalSearch').select()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'&&state.module&&canAccess(state.page)){e.preventDefault();openModal()}if(e.key==='Escape'){closeModal();document.getElementById('shortcutHelp')?.remove()}if(!e.ctrlKey&&!e.metaKey&&e.altKey&&e.key.toLowerCase()==='h'){e.preventDefault();go('hoje')}if(!e.ctrlKey&&!e.metaKey&&e.altKey&&e.key.toLowerCase()==='m'){e.preventDefault();go('minhaarea')}if(!e.ctrlKey&&!e.metaKey&&e.altKey&&e.key.toLowerCase()==='c'){e.preventDefault();go('calendario')}if(!e.ctrlKey&&!e.metaKey&&e.altKey&&e.key.toLowerCase()==='g'&&internalSession?.role==='manager'){e.preventDefault();go('governanca')}if(!e.ctrlKey&&!e.metaKey&&e.altKey&&e.key.toLowerCase()==='s'&&internalSession?.role==='manager'){e.preventDefault();go('saude')}if(e.key==='?'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')){e.preventDefault();showShortcutHelp()}});$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#collapseBtn').onclick=()=>{const on=!document.body.classList.contains('sidebar-collapsed');document.body.classList.toggle('sidebar-collapsed',on);setPref('sidebarCollapsed',on)};setInterval(()=>fetch('/api/heartbeat').catch(()=>{}),10000);fetch('/api/heartbeat').catch(()=>{});pollNewRequests();pollPersonalWork();setInterval(pollNewRequests,15000);setInterval(pollPersonalWork,15000);setupAutoLock()}
function init(){internalSession=loadInternalSession();if(!internalSession)return renderInternalLogin();document.getElementById('app').style.display='flex';startApp()}
init();
